
import {
    Grid,
    Typography,
} from "@mui/material";
import React, { useMemo } from "react";

import { cusReqMasterDataAtom, useRecoilState } from "../../../../Heplers";

export const HeaderMasterComp = ({ stageName = "Preparation", URLParams }) => {
    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);

    // console.log({ URLParams });


    return useMemo(() => {
        return (
            <Grid item container spacing={2} xs={12}>
                <Grid item container>

                    <Typography
                        variant="h6"
                        sx={{
                            color: "#333333",
                            fontWeight: "700",
                            fontSize: 18,
                            fontFamily: "poppins",
                        }}
                    >
                        {stageName} Stage
                    </Typography>
                    {!(URLParams.paramId.length < 6) && (<Typography sx={{
                        fontWeight: "bolder",
                        fontSize: 18,
                        fontFamily: "poppins", pl: 0.5, color: "#065036"
                    }} > | CUI: {URLParams.paramId}</Typography>)}


                    <Grid container mt={-2}>

                        <Typography
                            variant="h4"
                            sx={{
                                color: "#00261C",
                                paddingTop: "1%",
                                fontWeight: "550",
                                lineHeight: "42px",
                                fontSize: 20,
                            }}
                        >
                            {(URLParams.paramId.length < 6) ? 'New' : 'Update'} Customization Request
                        </Typography>
                    </Grid>
                </Grid>
                
            </Grid>
        );
    }, [Atom.cui]);
};
