import { Alert, Grid } from "@mui/material";
import React, { useMemo } from "react";

export const UnderDevAlert = ({text = "This page is UNDER DEVELOPMENT"}) => {
  return useMemo(
    () => (
      <Grid item xs={12} my={4} mx={1}>
        <Alert variant="filled" severity="warning">
            {text}
        </Alert>
      </Grid>
    ),
    []
  );
};
