import React, { useState } from "react";
import {
  Box,
  TextField,
  Button,
  MenuItem,
  Typography,
  Stack,
} from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import DrawerComp from "../Components/Drawer/drawer";
import Header from "../Components/Header/MainHeader";
import axiosInstance from "../Services/AxiosInstance";

const statesInIndia = [
  "Andhra Pradesh",
  "Arunachal Pradesh",
  "Assam",
  "Bihar",
  "Chhattisgarh",
  "Goa",
  "Gujarat",
  "Haryana",
  "Himachal Pradesh",
  "Jharkhand",
  "Karnataka",
  "Kerala",
  "Madhya Pradesh",
  "Maharashtra",
  "Manipur",
  "Meghalaya",
  "Mizoram",
  "Nagaland",
  "Odisha",
  "Punjab",
  "Rajasthan",
  "Sikkim",
  "Tamil Nadu",
  "Telangana",
  "Tripura",
  "Uttar Pradesh",
  "Uttarakhand",
  "West Bengal",
];

const userRoles = [
  "NLPSV",
  "PACS",
  "CPMU",
  "HO",
  "SI",
  "SPMU",
  "State",
  "RO",
  "SLIMC",
  "Admin"
];

export const CreateNewUser = () => {
  const [formData, setFormData] = useState({
    userName: "",
    userRole: "",
    email: "",
    resourceLocation: "",
    state: "",
    partner: "",
    deploymentDate: "",
    password: "",
    resourceCostPerMonth: "",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const validateEmail = (email) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const validatePassword = (password) => {
    const passwordRegex =
      /^(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;
    return passwordRegex.test(password);
  };
const reset=()=>{
  return(setFormData({
    userName: "",
    userRole: "",
    email: "",
    resourceLocation: "",
    state: "",
    partner: "",
    deploymentDate: "",
    password: "",
    resourceCostPerMonth: "",
  })
)}
  const handleSubmit = async () => {
    const {
      userName,
      userRole,
      email,
      resourceLocation,
      state,
      partner,
      deploymentDate,
      password,
      resourceCostPerMonth,
    } = formData;

    if (
      !userName ||
      !userRole ||
      !email ||
      !resourceLocation ||
      !state ||
      !partner ||
      !deploymentDate ||
      !password ||
      !resourceCostPerMonth
    ) {
      alert("All fields are mandatory!");
      return;
    }

    if (!validateEmail(email)) {
      alert("Invalid email format!");
      return;
    }

    if (!validatePassword(password)) {
      alert(
        "Password must be at least 8 characters long, include an uppercase letter, a lowercase letter, a number, and a special character."
      );
      return;
    }

    const payload = {
      userInformation: {
        userName,
        userRole,
        email,
        resourceLocation,
        state,
        partner,
        deploymentDate,
        password,
        resourceCostPerMonth: parseFloat(resourceCostPerMonth),
      },
    };

    try {
      const response = await axiosInstance.post(
        "https://epacspmc.co.in/prod_backend/api/v1/nabard/create",
        payload
      );
      alert("User created successfully!");
      console.log(response.data);
    } catch (error) {
      console.error("Error creating user:", error);
      alert("Failed to create user. Please try again.");
    }finally {
      reset();
    }
  };

  return (
    <div style={{ overflow: "hidden" }}>
      <style>
        {`
            .css-10hburv-MuiTypography-root{
              font-size:11px !important;
              font-family: Poppins 
            }
            .css-yb0lig{
              font-size:12px !important
            }
            `}
      </style>
      <CssBaseline />
      <Header />
      <DrawerComp listName={"Create New User"} />
      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: { xs: 2, md: 3 },
          backgroundColor: "#f4faf8",
          minHeight: "100vh",
          mt: 4
        }}
      >
        <Typography variant="h5" sx={{ mb: 3, fontFamily: "Poppins" }}>
          Create New User
        </Typography>
        <Stack spacing={2} sx={{ maxWidth: 600, margin: "0 auto" }}>
          <TextField
            label="User Name"
            name="userName"
            value={formData.userName}
            onChange={handleChange}
            fullWidth
            required
          />
          <TextField
            select
            label="User Role"
            name="userRole"
            value={formData.userRole}
            onChange={handleChange}
            fullWidth
            required
          >
            {userRoles.map((role) => (
              <MenuItem key={role} value={role}>
                {role}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            label="Email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            fullWidth
            required
          />
          <TextField
            // select
            label="Resource Location"
            name="resourceLocation"
            value={formData.resourceLocation}
            onChange={handleChange}
            fullWidth
            required
          >
            {/*{statesInIndia.map((state) => (*/}
            {/*  <MenuItem key={state} value={state}>*/}
            {/*    {state}*/}
            {/*  </MenuItem>*/}
            {/*))}*/}
          </TextField>
          <TextField
            select
            label="State"
            name="state"
            value={formData.state}
            onChange={handleChange}
            fullWidth
            required
          >
            {statesInIndia.map((state) => (
              <MenuItem key={state} value={state}>
                {state}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            label="Partner"
            name="partner"
            value={formData.partner}
            onChange={handleChange}
            fullWidth
            required
          />
          <TextField
            label="Deployment Date"
            name="deploymentDate"
            type="date"
            value={formData.deploymentDate}
            onChange={handleChange}
            fullWidth
            InputLabelProps={{ shrink: true }}
            required
          />
          <TextField
            label="Password"
            name="password"
            type="password"
            value={formData.password}
            onChange={handleChange}
            fullWidth
            required
          />
          <TextField
            label="Resource Cost Per Month"
            name="resourceCostPerMonth"
            type="number"
            value={formData.resourceCostPerMonth}
            onChange={handleChange}
            fullWidth
            required
          />
          <Button
            variant="contained"
            sx={{
              backgroundColor: "#065036",
              color: "#fff",
              "&:hover": { backgroundColor: "#044026" },
            }}
            onClick={handleSubmit}
          >
            Create New User
          </Button>
        </Stack>
      </Box>
    </div>
  );
};

export default CreateNewUser;