import React from "react";
import { Typography, Stack, Box, Paper } from "@mui/material";
import "./homepage.css";
import Bag from "../../Assets/bg_flower.png";
import Card from "../../Assets/cards.png";
import { useSpring, animated } from "react-spring";

function Number({ n }) {
  const { number } = useSpring({
    from: { number: 0 },
    number: n,
    delay: 100,
    config: { mass: 1, tension: 120, friction: 40 },
  });
  return (
    <animated.div style={{ textShadow: "0px 11px 5px rgba(0, 0, 0, 0.25)" }}>
      {number.to((n) => n.toFixed(0))}
    </animated.div>
  );
}

function Number1({ n }) {
  const { number } = useSpring({
    from: { number: 0 },
    number: n,
    delay: 100,
    config: { mass: 1, tension: 120, friction: 40 },
  });
  return (
    <>
      <Stack direction="row" spacing={1}>
        <animated.div
          style={{ textShadow: "0px 11px 5px rgba(0, 0, 0, 0.25)" }}
        >
          {number.to((n) => n.toFixed(0))}
        </animated.div>
        <Typography
          sx={{
            fontSize: "60px",
            color: "white",
            fontWeight: "600",
            height: "80px",
            textShadow: "0px 11px 5px rgba(0, 0, 0, 0.25)",
          }}
        >
          Cr.
        </Typography>
      </Stack>
    </>
  );
}

