import { Divider, Grid, TextField, Typography } from "@mui/material";
import {
  cusReqMasterDataAtom,
  SubmitErrorAlertAtom,
  useRecoilState,
  renderInputErrorLabel,
  ErrorLabelAtom,
  isEmptyObject,
  formatDate,
  StakeholderStatusArr,
  cusReqHOStatusListAtom,
  cusReqPriorityListAtom,
  isObjectCus,
  cleanGarbageCharacters
} from "../../../../Heplers";
import React, { useEffect, useMemo } from "react";
import { CusReqDropdown, defTextFieldOnChange } from "..";
import {getCookie} from "../../../../../Services/Cookies";

export const HOInputs = ({ formAtom, md, readOnly }) => {

  const [Atom, setAtom] = useRecoilState(formAtom);
  // forCheckingInputErrorLabelOnlyAfterSubmit
  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const defTextFieldOnChangeComParams = {
    setAtom, SubmitErrorAlert, setSubmitErrorAlert
  }

  useEffect(() => {
    // Setting Default Value
    // console.log(Atom)
    // For Update Form
    if (!isEmptyObject(Atom)) {
      typeof Atom.ho_inputs === 'string' && defTextFieldOnChange(Atom.ho_inputs, "ho_inputs", defTextFieldOnChangeComParams);
      typeof Atom.ho_date === 'number' && defTextFieldOnChange(formatDate(Atom.ho_date, 'db-yyyy-mm-dd'), "ho_date", defTextFieldOnChangeComParams);
    }
  }, []);

  if(getCookie("userRole") === "HO"){
    readOnly = false;
  }

  return useMemo(() => {

    // console.log(Atom.ho_inputs);

    return (

      <Grid item spacing={2} xs={12} md={md} container direction={'column'}>

        <Grid item>
          <Divider textAlign="left" sx={{ width: "50%", my: 2 }}>
            <Typography color={'GrayText'} fontSize={13} fontWeight="700">Head Office</Typography>
          </Divider>
          <TextField
            label="Date"
            variant="outlined"
            type="date"
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? formatDate(Atom.ho_date, 'db-yyyy-mm-dd') : null}
            fullWidth
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "ho_date", defTextFieldOnChangeComParams)}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>

        <Grid item>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={cusReqMasterDataAtom}
            listDataAtom={cusReqHOStatusListAtom}
            ddLabel="Status"
            dropdownName={"ho_status"}
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.ho_status : null}
            optData={StakeholderStatusArr}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />

        </Grid>

        <Grid item>
          <TextField
            label="Remarks"
            multiline
            variant="outlined"
            rows={4}
            fullWidth
            InputLabelProps={{
              shrink: true,
            }}
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.ho_inputs : null}
            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "ho_inputs", defTextFieldOnChangeComParams)}


            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}

          />
        </Grid>

        <Grid item>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={cusReqMasterDataAtom}
            listDataAtom={cusReqPriorityListAtom}
            ddLabel="Request Priority"
            dropdownName={"priority"}
            fetchMasterDataURL="fetchPriorityMasterData_CusReq"
            defVal={(!isEmptyObject(Atom) && typeof Atom.priority === "number") ? Atom.priority : 4}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>
      </Grid>


    );
  }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
