import React from 'react';
import {
    Box
} from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import DrawerComp from "../Drawer/drawer";
import Header from "../Header/MainHeader";

export const PowerBi = () => {

    return (

        <div
            style={{
                overflowX: "hidden",
                fontFamily: "Poppins",
                overflowY: "hidden",
            }}
        >
            <style>
                {`
      .video-container {
        position: relative;
        width: 100%;
        padding-top: 56.25%; /* 16:9 Aspect Ratio (height/width * 100) */
      }
      .video-container iframe {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
      }
      .css-10hburv-MuiTypography-root {
        font-size: 11px !important;
        font-family: Poppins;
      }
      .css-yb0lig {
        font-size: 12px !important;
      }
    `}
            </style>
            <Box sx={{display: "flex"}}>
                <CssBaseline/>
                <Header/>
                <DrawerComp listName={"Power BI - Dashboard"}/>
                <Box
                    component="main"
                    sx={{flexGrow: 1, p: {xs: 0, md: 0}, backgroundColor: "#f4faf8", marginTop: "90px",}}
                >

                    <div className="video-container">
                        <iframe title="CSPCP_Project Progress Report"
                                src="https://app.powerbi.com/view?r=eyJrIjoiZTk2ZWE1MjItODY2OS00Mzc0LThmZjAtMGI0M2M0MTJhYmFjIiwidCI6IjhlNjVkYzYzLTI5MjUtNDRkYy05YzAyLTk4YzNmMDUwNjllYyJ9"
                                frameborder="0" allowFullScreen="true"></iframe>
                    </div>
                </Box>
            </Box>
        </div>
    );
}