import React, { useMemo } from "react";
import {
    Fab,
    Grid,
    Typography,
    Box
} from "@mui/material";
import { AddCircleOutlineOutlined } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";

export const SiHeaderComponnent = () => {
    const navigate = useNavigate();
    return useMemo(() => {
        return (
            <Grid item container display={"flex"} justifyContent={"space-between"} sx={{ padding: "2%" }}>
                <Grid item sx={{ zoom: 0.7 }} alignItems={"center"} xs={6}>
                    <Typography
                        variant="h4"
                        sx={{
                            color: "#00261C",
                            paddingTop: "1%",
                            fontWeight: "550",
                            lineHeight: "42px",
                        }}
                    > SI Payment Summary
                    </Typography>
                </Grid>

                <Grid
                    item
                    display={"flex"}
                    justifyContent={"right"}
                    alignItems={"center"}
                    xs={6}
                    sx={{ zoom: 0.7 }}
                >
                    <Fab
                        sx={{ textTransform: "none" }}
                        color="success"
                        variant="extended"
                        onClick={() => navigate("/sipayments/new")}
                    >
                        <AddCircleOutlineOutlined sx={{ mr: 1 }} />
                        New SI Payment Request
                    </Fab>
                </Grid>
            </Grid>
        );
    }, []);
};
