import {
    Autocomplete,
    Chip,
    Divider,
    Grid,
    List,
    ListItem,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    TextField,
    Typography
} from "@mui/material";
import {
    SubmitErrorAlertAtom,
    useRecoilState,
    renderInputErrorLabel,
    ErrorLabelAtom,
    isEmptyObject,
    formatDate,
    cusReqBRFMasterDataAtom,
    isObjectCus,
    genUUID,
    currentDate,
    currentDatePlus14,
    cusReqCUIMasterDetailsAtom,
    useRecoilValue
} from "../../../../Heplers";
import React, { useEffect, useMemo } from "react";
import { defTextFieldOnChange, InputsFourthRowMasterData } from "..";



export const InputsFirstRowBRF = ({readOnly}) => {

    const CUIAtom = useRecoilValue(cusReqCUIMasterDetailsAtom);
    const [Atom, setAtom] = useRecoilState(cusReqBRFMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    // @ts-ignore
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);

    const defTextFieldOnChangeComParams = {
        setAtom, SubmitErrorAlert, setSubmitErrorAlert
    }

    const renderSavedbrd_points = () => {

        // console.log("brd_points", Atom.brd_points);


        // @ts-ignore
        if (Atom !== null && typeof Atom.brd_points === 'string') {
            // @ts-ignore
            const brd_points = Atom.brd_points !== null ? JSON.parse(`[${Atom.brd_points}]`) : []
            return <List sx={{ width: '100%', bgcolor: 'background.paper' }}>
                {brd_points.map((value, i) => {
                    const labelId = `checkbox-list-label-${value.name}`;

                    return (
                        <span key={genUUID()}>
                            <ListItem
                                key={value}
                                //   secondaryAction={
                                //     <IconButton edge="end" aria-label="comments">
                                //       <CommentIcon />
                                //     </IconButton>
                                //   }
                                disablePadding
                            >
                                <ListItemButton role={undefined}

                                    // onClick={handleToggle(value)} 

                                    dense>
                                    <ListItemIcon>
                                        {/* <Checkbox
                                            edge="start"
                                            checked={checked.indexOf(value) !== -1}
                                            tabIndex={-1}
                                            disableRipple
                                            inputProps={{ 'aria-labelledby': labelId }}
                                        /> */}
                                        <b>{i + 1}:</b>
                                    </ListItemIcon>
                                    <ListItemText id={labelId} primary={value.name} />
                                </ListItemButton>
                            </ListItem>
                            <Divider variant="inset" component="li" />
                        </span>
                    );
                })}
            </List>
        }

        return null


    }

    useEffect(() => {
        // Setting Default Value
        // console.log(Atom)
        // For Update Form
        if (
            CUIAtom !== null &&
            CUIAtom.brd !== null && isObjectCus(CUIAtom.brd) && !isEmptyObject(CUIAtom.brd)
        ) {
            // console.log("Updated Sett params", Atom.edor, Atom)
            defTextFieldOnChange(formatDate(Atom.edor, 'db-yyyy-mm-dd'), "dor", defTextFieldOnChangeComParams);
            defTextFieldOnChange(formatDate(Atom.start_date, 'db-yyyy-mm-dd'), 'start_date', defTextFieldOnChangeComParams);
            // defTextFieldOnChange(Atom.descrip, "descrip", defTextFieldOnChangeComParams);
            // defTextFieldOnChange(Atom.addto, "addto", defTextFieldOnChangeComParams);
        } else {
            // console.log("New Form Sett params", Atom.edor, Atom)
            defTextFieldOnChange(currentDate, "start_date", defTextFieldOnChangeComParams);
            defTextFieldOnChange(currentDatePlus14, "edor", defTextFieldOnChangeComParams);
        }
    }, []);

    return useMemo(() => {

        // console.log("Atom.brd_points", Atom.brd_points, typeof Atom.brd_points)
        // console.log(Atom.edor)
        return (
            <Grid spacing={2} container>

                <Grid item xs={12} md={4} sx={{ pb: { xs: 2 }, pt: { md: 1 } }}>
                    <TextField
                        label="Started On"
                        variant="outlined"
                        type="date"
                        defaultValue={(Atom !== null && typeof Atom.start_date === 'string') ? formatDate(Atom.start_date, 'db-yyyy-mm-dd') : currentDate}
                        fullWidth
                        required
                        InputLabelProps={{
                            shrink: true,
                        }}
                        onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "start_date", defTextFieldOnChangeComParams)}


                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                    {renderInputErrorLabel(ErrorLabel, Atom.start_date, "Required")}
                </Grid>


                <Grid item xs={12} md={4} sx={{ pb: { xs: 2 }, pt: { md: 1 } }}>
                    <TextField
                        label="Expected Date of BRF Resolution"
                        variant="outlined"
                        type="date"
                        defaultValue={(Atom !== null && typeof Atom.edor === 'string') ? formatDate(Atom.edor, 'db-yyyy-mm-dd') : null}
                        fullWidth
                        required
                        InputLabelProps={{
                            shrink: true,
                        }}
                        onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "edor", defTextFieldOnChangeComParams)}

                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                    {renderInputErrorLabel(ErrorLabel, Atom.edor, "Required")}
                </Grid>
                        <Grid item xs={12} md={4} sx={{ pb: { xs: 2 }, pt: { md: 1 } }}>
                            <InputsFourthRowMasterData formAtom={cusReqBRFMasterDataAtom} md={12} mt={0} readOnly={readOnly} />
                        </Grid>


                {renderSavedbrd_points()}


                <Grid item xs={12} md={12}>

                    <Typography sx={{color: "red", opacity: 0.7, fontSize: 10}}>To capture next BRD summary points press "Enter Key"</Typography>
                    <Typography sx={{color: "red", opacity: 0.7, fontSize: 10, mb: 2}}>Don't add ordering numbers to BRD Points - SLNO</Typography>
                    <Autocomplete
                        // @ts-ignore
                        onChange={(e, v) => {
                            if(readOnly)
                                return null;


                            if (Atom !== null && typeof Atom.brd_points === 'string') {
                                // @ts-ignore
                                const brd_points = Atom.brd_points !== null ? JSON.parse(`[${Atom.brd_points}]`) : []

                                brd_points.length > 0 && brd_points.forEach(v1 => v.push(v1.name))

                            }

                            // console.log(v);
                            defTextFieldOnChange(v, "brd_points", defTextFieldOnChangeComParams)
                        }}

                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}


                        multiple
                        id="tags-filled"
                        options={[].map((option) => option.title)}
                        // defaultValue={[top100Films[13].title]}
                        freeSolo
                        sx={{ width: "100%" }}
                        renderTags={(value, getTagProps) =>
                            value.map((option, index) => {
                                const { key, ...tagProps } = getTagProps({ index });
                                return (
                                    <Chip
                                        variant="outlined"
                                        label={option}
                                        key={key}
                                        {...tagProps}
                                    />
                                );
                            })
                        }
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                id="outlined-multiline-static"
                                label="BRD summary points"
                                multiline
                                variant="outlined"
                                // rows={2}
                                InputLabelProps={{ shrink: true }}
                                fullWidth
                                // @ts-ignore
                                required={typeof Atom.brd_points === 'undefined'}
                            // sx={{
                            //   // minWidth: '450px
                            //   paddingRight: '4%'
                            // }}


                                disabled={readOnly}
                                aria-readonly={readOnly}
                                readOnly={readOnly}
                                className={`${readOnly && 'readonlyStyle'}`}
                            />
                        )}
                    />
                    {Atom.brd_points === undefined ? renderInputErrorLabel(ErrorLabel, Atom.brd_points, "Required") : true}
                </Grid>
            </Grid>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
