import { linkToSplit_customizationrequestlisting, paramsFromURL } from "../../../Heplers";
import React, { useEffect, useMemo } from "react";
export default function CusReqListingHeader() {
  const urlParams = paramsFromURL({ linkToSplit: linkToSplit_customizationrequestlisting })

  useEffect(() => { }, []);

  return useMemo(() => {
    let headerElem = (
      <>
      </>
    );

    switch (String(urlParams.paramId).toLowerCase().replace(/%20/g, " ")) {
      case "business req. finalization":
        headerElem = (
          <>
          </>
        );
        break;

      case "development":
        headerElem = (
          <>
            <th
              scope="col"
              // className="mdTextAlignCenter"
              style={{ width: 120 }}
            >
              NLPSV Resource Name
            </th>
          </>
        );
        break;
      case "user acceptance":
        headerElem = (
          <>
            <th
              scope="col"
              // className="mdTextAlignCenter"
              style={{ width: 100 }}
            >
              Compliance On BRD
            </th>
          </>
        );
        break;

      default:
        break;
    }

    return (
      <thead>
        <tr>
          <th scope="col" style={{ width: 60 }}>
            CUI
          </th>
          <th scope="col" style={{ width: 250 }}>
            Customization Request
          </th>

          <th scope="col" style={{ width: 80 }}>
            State
          </th>

          <th scope="col" style={{ width: 80 }}>
            Assigned To
          </th>

          <th scope="col" style={{ width: 80 }}>
            Dates
          </th>
          <th scope="col" className="mdTextAlignCenter" style={{ width: 80 }}>
            Priority
          </th>
          <th scope="col" className="mdTextAlignCenter" style={{ width: 80 }}>
            Ageing
          </th>
          <th scope="col" className="mdTextAlignCenter" style={{ width: 150 }}>
            Pending Inputs
          </th>

          {headerElem}
          <th scope="col" className="mdTextAlignCenter" style={{ width: 80 }}>
            Action
          </th>
        </tr>
      </thead>
    );
  }, []);
}
