import { Box, Divider, Grid, Paper, Typography } from "@mui/material";
import CssBaseline from "@mui/material/CssBaseline";
import Toolbar from "@mui/material/Toolbar";
import React, { useEffect, useMemo } from "react";
import DrawerComp from "../../../Components/Drawer/drawer";
import MainHeader from "../../../Components/Header/MainHeader";
import {
  CPMUInputs,
  CusReqDetailsCard,
  HeaderMasterComp,
  InputsFourthRowMasterData,
  NLPSVInputs,
  PageLoadingElem,
  SIInputs,
  SPMUInputs,
  StateInputs,
  UnderDevAlert
} from "./Components";
import {
  cusReqDEVMasterDataAtom,
  cusReqCUIMasterDetailsAtom,
  ErrorLabelAtom,
  invalidURLAlert,
  isEmptyObject,
  pageLoadingAtom,
  paramsFromURL,
  SubmitErrorAlertAtom,
  useRecoilState,
  cusReqBRFMasterDataAtom, NAWarningLabel
} from "../../Heplers";
import axiosInstance from "../../../Services/AxiosInstance";

import { useNavigate } from "react-router-dom";
import { isObject } from "@mui/x-data-grid/internals";
import { InputsFirstRowDEV } from "./Components/DEVForm/InputsFirstRowDEV";
import { DEVDataSubmit } from "./Components/DEVForm/DEVDataSumbit";
import {StCBInputs} from "./Components/PreparationForm/StCBInputs";
import {getCookie} from "../../../Services/Cookies";

export default function CustomizationRequestDEVEntryForm() {

  const [Atom, setAtom] = useRecoilState(cusReqCUIMasterDetailsAtom);
  const navigate = useNavigate();


  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const [AtomDEV, setAtomDEV] = useRecoilState(cusReqDEVMasterDataAtom);

  const APICall = async (reqData) => {

    setPageLoading(true);
    axiosInstance({
      method: "post",
      url: "fetchCUIMasterData",
      data: reqData,
    }).then(function (response) {
      if (!isObject(response.data) || isEmptyObject(response.data)) {
        invalidURLAlert(`CUI: ${reqData.cui}`, "Invalid Customization Unique Identification Number")
      } else {

        const parsedRes = {
          pre: JSON.parse(response.data.pre),
          brd: JSON.parse(response.data.brd),
          dev: JSON.parse(response.data.dev),
          uat: JSON.parse(response.data.uat),
        };

        setAtom(parsedRes);


        setAtomDEV((prevState) => ({

          // @ts-ignore
          ...prevState,
          ...parsedRes.dev,
          ...JSON.parse(parsedRes.dev.dev_reviews_ongoing)

        }));
        setPageLoading(false)
      }
      // console.log('Data =>', response.data);

    })
      .catch(function (error) {
        setPageLoading(false)
        console.error(error);
      });

  };

  const [PageLoading, setPageLoading] = useRecoilState(pageLoadingAtom);
  const URLParams = paramsFromURL({
    linkToSplit: "customizationrequestdev/",
  })
  useEffect(() => {
    window.scrollTo({
      top: 0,
      left: 0,
      behavior: "smooth",
    });





    // console.log('Listing', URLParams)
    if (URLParams.paramId !== undefined && URLParams.paramId != "") {
      // @ts-ignore
      // if (isNaN(URLParams.paramId)) {
      if (URLParams.paramId.length < 6) {
        invalidURLAlert(`CUI: ${URLParams.paramId}`, "Invalid Customization Unique Identification Number")
      } else {
        APICall({ cui: URLParams.paramId });
      }
    }
    return () => {
      // Clearing Page Used Variables

      // @ts-ignore
      setAtom({})
      setAtomDEV({})

      setSubmitErrorAlert(false);
      setErrorLabel(false);
      setPageLoading(false)
    };

  }, []);

  const readOnly = (getCookie("userRole") !== "SPMU" && getCookie("userRole") !== "CPMU");

  const renderMainContent = () => {
    return <>
      <HeaderMasterComp URLParams={URLParams} stageName="Development" />

      <Grid container spacing={1} pt={1}>

        <Grid item md={4} xs={12}>
          <CusReqDetailsCard />
        </Grid>

        <Grid item md={8} xs={12}>
          <Paper elevation={2} sx={{ p: 2, mb: 4 }}>

            <InputsFirstRowDEV readOnly={readOnly}/>

            <Grid item xs={12} mt={4}>
              <Divider textAlign="left">
                <Typography color={'GrayText'} fontSize={14} fontWeight="bold">Review Meeting - Stakeholder Inputs</Typography>
              </Divider>

              {NAWarningLabel()}

            </Grid>

            <Grid container spacing={2} direction={"row"}>
              <SIInputs formAtom={cusReqDEVMasterDataAtom} md={6} readOnly={readOnly}/>
              <StateInputs formAtom={cusReqDEVMasterDataAtom} md={6} readOnly={readOnly}/>
            </Grid>

            <Grid container spacing={2} direction={"row"}>
              <StCBInputs formAtom={cusReqDEVMasterDataAtom} md={6} readOnly={readOnly}/>
              <SPMUInputs formAtom={cusReqDEVMasterDataAtom} md={6} readOnly={readOnly}/>
            </Grid>

            <Grid container spacing={2} direction={"row"}>

              <CPMUInputs formAtom={cusReqDEVMasterDataAtom} md={6} readOnly={readOnly}/>

              <NLPSVInputs formAtom={cusReqDEVMasterDataAtom} md={6} edodInput={false} edorfInput={false} plannedGoLive={false} readOnly={readOnly}/>

            </Grid>

            <DEVDataSubmit />
          </Paper>
        </Grid>
      </Grid>


    </>
  }

  return useMemo(() => {
    return (
      <div>
        <style>
          {`
                    .css-10hburv-MuiTypography-root{
                      font-size:11px !important;
                      font-family: Poppins 
                    }
                    .css-yb0lig{
                      font-size:12px !important
                    }
                    `}
        </style>

        <Box sx={{ display: "flex", mt: 5 }}>
          <CssBaseline />
          {/* @ts-ignore*/}
          <MainHeader />
          <DrawerComp listName={"Customization Request"} />
          <Box
            component="main"
            sx={{
              flexGrow: 1,
              backgroundColor: "#f4faf8",
              px: 1,
              // pr: 4,
              // @ts-ignore
              // height: isEmptyObject(URLParams) ? "100vh" : "auto",
            }}
          >
            <Toolbar />

            {/*<UnderDevAlert />*/}
            <PageLoadingElem />

            {!PageLoading && renderMainContent()}


          </Box>
        </Box>
      </div>
    )
  }, [PageLoading]);
}
