import React, { useEffect, useState, useMemo } from 'react';
import { useRecoilState } from 'recoil';
import { Grid, Button, Typography, Card, Toolbar, Box, Paper, CssBaseline, TextField, MenuItem, RadioGroup, FormControlLabel, Radio, Alert } from '@mui/material';
import DrawerComp from "../../Components/Drawer/drawer";
import MainHeader from "../../Components/Header/MainHeader";
import axiosInstance from '../../Services/AxiosInstance';
import { siFormDataAtom, siStateListAtom, siNameListAtom, siPaymentMilestoneListAtom, siErrorLabelAtom } from '../../RAS_updates/Heplers/siFormRecoil';
import { successAndGoBackAlert, renderSubmitErrorAlert } from '../../RAS_updates/Heplers';
import { getCookie } from '../../Services/Cookies';
import SaveAsIcon from '@mui/icons-material/SaveAs';
import { useParams, useNavigate } from 'react-router-dom';
import { CusReqDropdownSIPayment } from "./CusReqDropdownSIPayment";

const NewSIPaymentRequestForm = ({ mode }) => {

  const [formData, setFormData] = useRecoilState(siFormDataAtom);
  const [error, setError] = useState('');
  const [siNameData, setSiNameData] = useState([]); // All state+SI data from API
  const [siNameOptions, setSiNameOptions] = useRecoilState(siNameListAtom);
  const [defStatevalue, setDefStateValue] = useState({ id: "" });
  const [defSiNameValue, setDefSiNameValue] = useState({ siId: "" });
  const [disbursedBySI, setDisbursedBySI] = useState(null);
  const params = useParams();
  const navigate = useNavigate();
  const initialFormData = {
    state: { code: 0 },
    siName: { id: "" },
    paymentMilestone: { id: 0 },
    invoiceNumber: "",
    billRaisedDate: "",
    invoiceAmount: 0,
    raisedTo: "",
    slimcMeetingScheduledOn: "",
    slimcApprovalDate: "",
    paymentDisbursedAmt: 0,
    paymentDisbursedOn: "",
    PaymentEligibility: "",
    newPaymentEligibility: "",
    recommendedChange: "",
    siPaymentPendency: 0,
    siPaymentPendencyDate: "",
    remarks: "",
    status: "",
  };
  const user_id = getCookie("resourceId");

  useEffect(() => {
    axiosInstance.post('/si-payments/siswithStates').then(res => {
      if (res.data && Array.isArray(res.data)) {
        setSiNameData(res.data);
      }
    });
  }, [formData.stateUt]);

  useEffect(() => {
    if (
      formData.stateUt &&
      formData.stateUt.id &&
      formData.siName &&
      formData.siName.siId
    ) {
      axiosInstance
        .post(
          `/si-payments/disbursed-amount?siId=${formData.siName.siId}&stateUt=${formData.stateUt.id}`
        )
        .then((res) => {
          if (res.data) {
            setDisbursedBySI(res.data);
          } else {
            setDisbursedBySI(null);
          }
        })
        .catch(() => setDisbursedBySI(null));
    } else {
      setDisbursedBySI(null);
    }
  }, [formData.stateUt, formData.siName]);

  useEffect(() => {
    // Only run if state is selected and siNameData is loaded
    if (formData.stateUt && formData.stateUt.id && siNameData.length > 0) {
      const match = siNameData.find(
        (item) => item.stateId === formData.stateUt.id
      );
      console.log("Matched state data", match);

      setSiNameOptions(match && Array.isArray(match.sis) ? match.sis : []);
    } else {
      setSiNameOptions([]); // No state selected, clear options
    }
  }, [formData.stateUt, siNameData, setSiNameOptions]);

  const handleChange = (field) => (event) => {
    setFormData((prev) => ({
      ...prev,
      [field]: event.target.value
    }));
  };
  // Fetch form data by ID if in update mode
  useEffect(() => {
    if (mode === "update" && params.id) {
      axiosInstance.post(`/si-payments/get-by-id?id=${params.id}`).then(res => {
        if (res.data) {
          setFormData(res.data);
        }
      });
    } else if (mode === "create") {
      setFormData(initialFormData);
    }
    // eslint-disable-next-line
  }, [mode, params.id]);

  const handleSubmit = async () => {
    if (!formData.stateUt || !formData.stateUt.id) {
      setError('State is required.');
      return;
    }
    if (!formData.siName || !formData.siName.siId) {
      setError('SI Name is required.');
      return;
    }
    if (!formData.paymentMilestone || !formData.paymentMilestone.id) {
      setError('Payment Milestone is required.');
      return;
    }
    if (!formData.invoiceNumber || formData.invoiceNumber.trim() === '') {
      setError('Invoice Number is required.');
      return;
    }
    if (!formData.billRaisedDate || formData.billRaisedDate.trim() === '') {
      setError('Bill Raised Date is required.');
      return;
    }
    if (!formData.invoiceAmount || Number(formData.invoiceAmount) <= 0) {
      setError('Invoice Amount must be greater than 0.');
      return;
    }
    // if (!formData.raisedTo || formData.raisedTo.trim() === '') {
    //   setError('Raised To is required.');
    //   return;
    // }
    if (!formData.status || formData.status.trim() === '') {
      setError('Status is required.');
      return;
    }

    setError(''); // Clear error if validation passes
    try {
      const request_body = {
        "createdBy": user_id,
        "stateUt": formData.stateUt.id,
        "siId": formData.siName.siId,
        "paymentMilestone": {
          "id": formData.paymentMilestone.id,
        },
        "invoiceNumber": formData.invoiceNumber,
        "billRaisedDate": formData.billRaisedDate,
        "invoiceAmount": formData.invoiceAmount,
        "raisedTo": "RCS",
        "slimcMeetingScheduledOn": formData.slimcMeetingScheduledOn,
        "slimcApprovalDate": formData.slimcApprovalDate,
        "paymentDisbursedAmt": formData.paymentDisbursedAmt,
        "paymentDisbursedOn": formData.paymentDisbursedOn,
        "paymentEligibility": formData.paymentEligibility,
        "newPaymentEligibility": formData.newPaymentEligibility,
        "recommendedChange": formData.recommendedChange,
        "siPaymentPendency": formData.siPaymentPendency,
        "siPaymentPendencyDate": formData.siPaymentPendencyDate,
        "remarks": formData.remarks,
        "status": formData.status,
      }
      if (mode === "update" && params.id) {
        request_body.id = params.id;
      }

      const res = await axiosInstance.post(`/si-payments/${mode}`, request_body);
      console.log("the response is ->", res);
      if (res && res.status === 200) {
        console.log("response message", res.data.message);
        successAndGoBackAlert('Submitted successfully!');
      } else {
        renderSubmitErrorAlert('not Submitted successfully!');
      }
      setFormData(initialFormData);
    } catch (err) {
      renderSubmitErrorAlert('Error submitting form!');
    }
  };

  const getIndianFinancialYear = (dateStr) => {
    const d = new Date(dateStr)
    const m = d.getMonth() // 0 = Jan, ..., 11 = Dec
    const y = d.getFullYear()
    return (m >= 3)
      ? `${y}-${y + 1}`       // April – December → this FY
      : `${y - 1}-${y}`       // January – March → previous FY :contentReference[oaicite:1]{index=1}
  }

  const vertiInputsPadding = {
    pb: { xs: 2 },
  };

  return (
    console.log("Si disbured amount", disbursedBySI),
    <div style={{ overflowX: "hidden" }}>
      <style>
        {`
          .css-10hburv-MuiTypography-root{
            font-size:11px !important;
            font-family: Poppins 
          }
          .css-yb0lig{
            font-size:12px !important
          }
        `}
      </style>
      <Box sx={{ display: "flex" }}>
        <CssBaseline />
        <MainHeader />
        <DrawerComp listName={"SI Payments"} />
        <Box
          component="main"
          sx={{
            flexGrow: 1,
            backgroundColor: "#f4faf8",
            px: 1,
          }}>
          <Toolbar />

          <Grid item xs={12} mt={4}>

            <Typography
              variant="h6"
              sx={{
                color: "#333333",
                fontWeight: "700",
                fontSize: 18,
                fontFamily: "poppins",
              }}
            >
              SI Invoices
            </Typography>
          </Grid>
          <Grid container mt={-2}>
            <Typography
              variant="h4"
              sx={{
                color: "#00261C",
                paddingTop: "1%",
                fontWeight: "550",
                lineHeight: "42px",
                fontSize: 20,
              }}
            >
              System Integrator Invoice Payment Form
            </Typography>
          </Grid>

          <Paper elevation={2} sx={{ mb: 4, mt: 2 }}>
            <Grid container spacing={2} sx={{ padding: "2%" }}>
              {/* {error && (
                <Grid item xs={12}>
                  <Alert severity="error">{error}</Alert>
                </Grid>
              )} */}
              {/* State Dropdown */}
              {error && (
                <Grid item xs={12}>
                  <Alert severity="error">{error}</Alert>
                </Grid>
              )}
              <Grid item xs={12} sm={4} sx={{ ...vertiInputsPadding }}>
                <CusReqDropdownSIPayment
                  // @ts-ignore
                  formDataAtom={siFormDataAtom}
                  listDataAtom={siStateListAtom}
                  ddLabel="State/ UT"
                  dropdownName="stateUt"
                  fetchMasterDataURL="fetchStateMasterData_CusReq"
                  defVal={mode === 'update' ? formData.stateUt : ""}
                  mode={mode}
                  // @ts-ignore
                  optionLabel={["StateNameAndCode", "name", "short_name", "code"]}
                  required
                />
              </Grid>

              {/* SI Name Dropdown */}
              <Grid item xs={12} sm={4} sx={{ ...vertiInputsPadding, pt: { md: 1 } }}>
                <CusReqDropdownSIPayment
                  // @ts-ignore
                  formDataAtom={siFormDataAtom}
                  // @ts-ignore
                  listDataAtom={siNameListAtom}
                  ddLabel="SI Name"
                  dropdownName="siName"
                  fetchMasterDataURL="si-payments/siswithStates"
                  // @ts-ignore
                  optionLabel={["sis", "state", "siId"]}
                  required
                />

              </Grid>

              {/* Payment Milestone Dropdown */}
              <Grid item xs={12} sm={4}>
                <CusReqDropdownSIPayment
                  // @ts-ignore
                  formDataAtom={siFormDataAtom}
                  listDataAtom={siPaymentMilestoneListAtom}
                  ddLabel="Payment Milestone"
                  dropdownName="paymentMilestone"
                  fetchMasterDataURL="milestone/getmilestones"
                  // @ts-ignore
                  optionLabel={["name", "id"]}
                  defVal={formData.paymentMilestone}
                  required
                />
              </Grid>

              {/* Invoice Number */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="Invoice Number"
                  type="string"
                  value={formData.invoiceNumber || ''}
                  onChange={handleChange('invoiceNumber')}
                  InputLabelProps={{ shrink: true }}
                  required
                />
              </Grid>


              {/* Invoice Amount */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="Invoice Amount (in Crore)"
                  type="number"
                  value={formData.invoiceAmount || ''}
                  onChange={handleChange('invoiceAmount')}
                  InputLabelProps={{ shrink: true }}
                  required
                />
              </Grid>

              {/* Bill Raised Date */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="Bill Raised Date"
                  type="date"
                  value={formData.billRaisedDate || ''}
                  onChange={handleChange('billRaisedDate')}
                  InputLabelProps={{ shrink: true }}
                  required
                />
                 {formData.billRaisedDate && (
                  <Typography variant="caption">
                    Financial Year (FY – {getIndianFinancialYear(formData.billRaisedDate)})
                  </Typography>
              )}

              </Grid>
             
              {/* Status Radio */}
              <Grid item xs={12} sm={4} pb={2}>
                <Typography style={{
                  fontSize: "small",
                  opacity: 0.7,
                  fontWeight: 400
                }}>Status <span
                  aria-hidden="true"
                  className="MuiFormLabel-asterisk MuiInputLabel-asterisk css-wgai2y-MuiFormLabel-asterisk"> *</span></Typography>
                <RadioGroup
                  row
                  value={formData.status || ''}
                  onChange={handleChange('status')}
                  aria-required={true}
                >
                  <FormControlLabel value="PAID" control={<Radio />} label="Paid" />
                  <FormControlLabel value="UNPAID" control={<Radio />} label="Unpaid" />
                </RadioGroup>
              </Grid>


              {/* Raised To Radio */}
              {/* <Grid item xs={12} sm={6}>
                <Typography>Raised To *</Typography>
                <RadioGroup
                  row
                  value={formData.raisedTo || ''}
                  onChange={handleChange('raisedTo')}
                >
                  <FormControlLabel value="RCS" control={<Radio />} label="RCS" />
                  <FormControlLabel value="StCB" control={<Radio />} label="StCB" />
                </RadioGroup>
              </Grid> */}

              {/* Payment Disbursed Amount */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="Payment Disbursed Amount"
                  type="number"
                  value={formData.paymentDisbursedAmt || ''}
                  onChange={handleChange('paymentDisbursedAmt')}
                  InputLabelProps={{ shrink: true }}
                />
                {disbursedBySI !== null && (
                  <Typography variant="caption">
                    Payment Disbursed by SI: {disbursedBySI} Cr
                  </Typography>
                )}
              </Grid>
              {/* Payment Disbursed On */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="Payment Disbursed On"
                  type="date"
                  value={formData.paymentDisbursedOn || ''}
                  onChange={handleChange('paymentDisbursedOn')}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>
              {/* SLIMC Meeting Scheduled On */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  variant="outlined"
                  label="SLIMC Meeting Scheduled On"
                  type="date"
                  value={formData.slimcMeetingScheduledOn || ''}
                  onChange={handleChange('slimcMeetingScheduledOn')}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>

              {/* SLIMC Approval Date */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  variant="outlined"
                  label="SLIMC Approval Date"
                  type="date"
                  value={formData.slimcApprovalDate || ''}
                  onChange={handleChange('slimcApprovalDate')}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>
              {/* SI Payment Pendency (Crore) */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="SI Payment Pendency (Crore)"
                  type="number"
                  value={formData.siPaymentPendency || ''}
                  onChange={handleChange('siPaymentPendency')}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>
              {/* SI Payment Pendency Date */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="SI Payment Pendency Date"
                  type="date"
                  value={formData.siPaymentPendencyDate || ''}
                  onChange={handleChange('siPaymentPendencyDate')}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>

              {/* Eligibility till 31st March 2025 */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="Eligibility till 31st March 2025"
                  multiline
                  rows={2}
                  value={formData.paymentEligibility || ''}
                  onChange={handleChange('paymentEligibility')}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>
              {/* New Eligibility if Terms Revised */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="New Eligibility if Terms Revised"
                  multiline
                  rows={2}
                  value={formData.newPaymentEligibility || ''}
                  onChange={handleChange('newPaymentEligibility')}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>
              {/* Recommended Change in Clause */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="Recommended Change in Clause"
                  multiline
                  rows={2}
                  value={formData.recommendedChange || ''}
                  onChange={handleChange('recommendedChange')}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>

              {/* Remarks */}
              <Grid item xs={12} sm={4} pb={2}>
                <TextField
                  fullWidth
                  label="Remarks"
                  multiline
                  rows={2}
                  value={formData.remarks || ''}
                  onChange={handleChange('remarks')}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>


              <Grid item xs={12} display="flex" justifyContent="flex-end" gap={2}>
                <Button
                  sx={{ mt: 1, minWidth: 100, textTransform: 'none' }}
                  variant="outlined"
                  color="error"
                  onClick={() => setFormData(initialFormData)}
                >
                  Reset
                </Button>
                <Button
                  sx={{ mt: 1, minWidth: 100, textTransform: 'none' }}
                  variant="outlined"
                  color="secondary"
                  onClick={() => navigate(-1)} // Go back to previous page
                >
                  Cancel
                </Button>
                <Button
                  variant="contained"
                  color="success"
                  onClick={handleSubmit}
                  sx={{ minWidth: 100, mt: 1, ml: 1, textTransform: 'none' }}
                >
                  {mode === "update" ? "Update" : "Submit"} <SaveAsIcon sx={{ fontSize: 14 }} />
                </Button>
              </Grid>
            </Grid>
          </Paper>
        </Box>
      </Box>
    </div>
  );
};

export default NewSIPaymentRequestForm;