import {
    Button, Chip,
    Divider,
    Grid,
    Typography,
} from "@mui/material";
import React, { useMemo } from "react";
import {
    cusReqCUIMasterDetailsAtom, displayDownloadableFilesLinks,
    genUUID,
    useRecoilValue,
} from "../../../../Heplers";
import moment from "moment";
import { CardStagesHeader, createrArrOfInputs, inputsRender, pendingInputsRender, systemCreationRender } from "./CusReqDetailsCard_Pre";
import { Link, useNavigate } from "react-router-dom";
import {chipSX} from "../CusReqDatalisting";


export function CusReqDetailsCard_BRD() {
    const Atom = useRecoilValue(cusReqCUIMasterDetailsAtom);
    const navigate = useNavigate();
    return useMemo(() => {
        const { brd, pre } = Atom;

        if (brd === null) {
            return <>
            
            {CardStagesHeader("Business Requirement Finalization")}
                            <b>Not Started:</b>
             {/* <Grid item>
                    <Link to={`/customizationrequestbrf/${pre.cui}`}>
                        <Button sx={{ minWidth: "unset", borderRadius: 10, fontSize: 10, p: "0.2px 15px" }} size="small" variant="outlined" color="primary" disableElevation >Add Business Requirement Finalization Details</Button>
                    </Link>

                </Grid> */}
                
                </>
        }


        const brd_points = brd.brd_points !== null ? JSON.parse(`[${brd.brd_points}]`) : []
        // console.log(brd_points);

        const pendingInputs = [];
        const stakeholderInputs = [];

        createrArrOfInputs(brd, 'si', pendingInputs, stakeholderInputs);
        createrArrOfInputs(brd, 'state', pendingInputs, stakeholderInputs);
        createrArrOfInputs(brd, 'stcb', pendingInputs, stakeholderInputs);
        createrArrOfInputs(brd, 'slimc', pendingInputs, stakeholderInputs);
        createrArrOfInputs(brd, 'spmu', pendingInputs, stakeholderInputs);
        createrArrOfInputs(brd, 'ro', pendingInputs, stakeholderInputs);
        createrArrOfInputs(brd, 'cpmu', pendingInputs, stakeholderInputs);
        createrArrOfInputs(brd, 'nlpsv', pendingInputs, stakeholderInputs);

        const arr = (brd.brd_file !== undefined && brd.brd_file !== null && brd.brd_file.length > 0) ? brd.brd_file.split(',') : [];
        console.log(brd, arr)

        return (
            <>
                {CardStagesHeader("Business Requirement")}

                <b>Started On:</b> {moment(brd.start_date, "YYYY-MM-DD").format("DD-MMM-YY")}


                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Status :</b> <br />
                {
                    brd.inputs_closed === 'Yes' ? <Chip size="small"  className="inputRecChip" label="Closed" color="success" sx={chipSX}/> : <Chip size="small" className="inputRecChip"  label="Pending" color="error" sx={{...chipSX, backgroundColor: "#B71C1C"}}/>
                }


                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Assigned To:</b><br /> {brd.assigned_to}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Expected Date of BRF Resolution:</b> <br /> {moment(brd.edor, "YYYY-MM-DD").format("DD-MMM-YY")}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b key={genUUID()}>BRD Major Points:</b>
                {brd_points.length > 0 && (brd_points.map((v, i) => (
                    <Grid ml={1} key={v.id} display={"flex"} container direction={"row"}><Typography sx={{ fontWeight: 600, fontSize: 12, pr: 0.5 }}>{i + 1}:</Typography>{v.name}</Grid>
                )))}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Ageing:</b> <br /> {brd.ageing}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Expected Date of Deployment:</b> <br /> {brd.edod !== null && moment(brd.edod, "YYYY-MM-DD").format("DD-MMM-YY")}

                {pendingInputsRender(pendingInputs)}

                {inputsRender(stakeholderInputs)}

                <Divider sx={{ my: 1, width: "25%" }} />
                <b>Uploaded Documents:</b> <br /> {displayDownloadableFilesLinks(arr)}

                {systemCreationRender(brd)}

            </>
        );
    }, [])
}
