import axiosInstance from "./AxiosInstance";
import { clearCookie, getCookie, setCookie } from "./Cookies";

export const logOutURL = () => {

  if(
    String(window.location.href).toLocaleLowerCase().indexOf("/dev_server") !== -1){
    return "/dev_server"
  } else if(String(window.location.href).toLocaleLowerCase().indexOf("/aws_server") !== -1){
    return "/aws_server"
  } else if(String(window.location.href).toLocaleLowerCase().indexOf("/prod_server") !== -1){
    return "/prod_server"
  }
  return "/"

  // Earlier
  if (window !== undefined) {
    if (
      String(window.location.hostname).toLowerCase() === "localhost" ||
      String(window.location.hostname).toLowerCase() === "127.0.0.1"
    ) {
      return "/nabard/";
    } 

    if (
      String(window.location.hostname).toLowerCase() ===
      "pwc-adv-in-emerging-technologies.southindia.cloudapp.azure.com"
    ) {
      if (String(window.location.pathname).indexOf("-dev") !== -1) {
        return "/nabard-dev/";
      }
      if (String(window.location.pathname).indexOf("-stage") !== -1) {
        return "/nabard-stage/";
      } else {
        // For Live
        return "/nabard/";
      }
    }
  }
}

export const AutoLogout = () => {
  const config = {
    headers: {
      "access-token": getCookie("token"),
      email: getCookie("email2"),
      Authorization: `Bearer ${getCookie("token")}`,
      "Content-Type": "application/json",
    },
  };
  const requestData = {
    email: getCookie("email2"),
  };
  axiosInstance
    .post(
      "authenticate/logoff",
      requestData,
      config
    )
    .then((response) => {
      clearCookie("email2");
      clearCookie("token");
      clearCookie("userName");
      clearCookie("loginStatus");
      clearCookie("userRole");
      clearCookie("state");
      clearCookie("email");
      clearCookie("resourceId");
      window.location.href = logOutURL();
    })
    .catch((error) => {
      console.error("Error fetching data:", error);
      clearCookie("email2");
      clearCookie("token");
      clearCookie("userName");
      clearCookie("loginStatus");
      clearCookie("userRole");
      clearCookie("state");
      clearCookie("email");
      clearCookie("resourceId");
      window.location.href = logOutURL();
    });
  // clearCookie("loginStatus");
  // clearCookie("userName");
  // window.location = "/";
};
