import { Button, Grid, TextField } from "@mui/material";
import React, { useEffect, useMemo, useState } from "react";
import ReactJson from "react-json-view";
import axiosInstance from "../../../Services/AxiosInstance";

const APITestPage = () => {
  let called = false;
  useEffect(() => {
    // APICall("fetchStatusMasterData_CusReq");
    // APICall("fetchStateMasterData_CusReq");
  }, []);

  const [APIURL, setAPIURL] = useState("getTop3States");
  const [APIRES, setAPIRES] = useState({});

  const APICall = () => {
    axiosInstance
      .post(APIURL)
      .then((response) => {
        console.log(response);
        // console.log('Parse One',JSON.parse(response.data.data));
        // setAPIRES(JSON.stringify(response.data));
        // @ts-ignore
        setAPIRES(response);
      })
      .catch((error) => {
        console.error("Error fetching data:", error);
      });
  };

  return useMemo(() => {
    return (
      <Grid
        item
        container
        sx={{ p: 2 }}
        direction="row"
        justifyContent="flex-end"
        alignItems="center"
      >
        <Grid item>
          <TextField
            variant="outlined"
            label="API URL"
            defaultValue={APIURL}
            fullWidth
            InputLabelProps={{
              shrink: true,
            }}
            InputProps={
              {
                // readOnly: true,
              }
            }
            required
            onChange={(e) => setAPIURL(e.target.value)}
          />

          <Button
            onClick={() => APICall()}
            sx={{ mt: 1 }}
            variant="outlined"
            color="warning"
          >
            Fetch Data
          </Button>
        </Grid>

        <Grid>
          {/* <Alert severity="info">{APIRES}</Alert> */}
          <ReactJson src={APIRES} />
        </Grid>
      </Grid>
    );
  }, [APIURL, APIRES]);
};

export default APITestPage;
