import { atom } from "recoil";
import { urlParamsDataAtomType } from "./Types";

export * from "./CusReqRecoil";
export * from "./siFormRecoil";

export const URLParamsAtom = atom({
  key: "URLParamsAtom",
  default: urlParamsDataAtomType,
});

export const pageLoadingAtom = atom({
  key: "pageLoadingAtom",
  default: true,
});

export const dataListingLoadingAtom = atom({
  key: "dataListingLoadingAtom",
  // false because data will be loading generally in first mount pageload
  default: false,
});

export const defAtom = atom({
  key: "defAtom", // unique ID (with respect to other atoms/selectors)
  default: "",
});

export const defListAtom = atom({
  key: "defListAtom", // unique ID (with respect to other atoms/selectors)
  default: [],
});

