import {
    AddchartOutlined,
    AddHomeOutlined,
    AppRegistrationOutlined, ApprovalOutlined,
    AppsOutlined,
    CloudCircleOutlined,
    CloudDownload,
    PointOfSaleOutlined,
    SummarizeOutlined,
} from "@mui/icons-material";
import {CardContent, CircularProgress, Grid} from "@mui/material";
import Paper from "@mui/material/Paper";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Typography from "@mui/material/Typography";
import {
    API_Endpoint,
    isARDBCusReqTabActive,
    overViewDataAtom,
    overViewTabAtom,
    successAndGoBackAlert,
    useRecoilValue
} from "../../../Heplers";
import AssignmentTurnedInIcon from '@mui/icons-material/AssignmentTurnedIn';
import * as React from "react";
import {useEffect, useMemo} from "react";
import {OverviewCardStagesListPenAndClosedOnly} from "./OverviewCardStagesListPenAndClosedOnly";
import moment from "moment/moment";
import axios from "axios";

export const OverviewCardPenAndClosedOnly = () => {
    const data = useRecoilValue(overViewDataAtom);

    const cusReqTabIndex = useRecoilValue(overViewTabAtom);

    const [processing, setProcessing] = React.useState(false);

    // console.log({ v, RGDate })


    const downloadCusReq = () => {
        setProcessing(true);

        // console.log(ReportCardsArr);
        // return;

        let contentType =
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

        const RGDate = moment(new Date());

        let fileName = `Overall_Summary_${cusReqTabIndex.replace('_tab', '').toUpperCase()}_${moment(RGDate).format("DD_MM_YYYY")}.xlsx`;

        const config = {
            method: "post",
            url: `${API_Endpoint()}/file/download/overallsummaryreport`,
            responseType: "blob",
            data: {
                fileName,
                date: moment(RGDate).add(1, 'days').format("YYYY-MM-DD"),
                is_ardb: isARDBCusReqTabActive(cusReqTabIndex),
            }
        };

        // @ts-ignore
        axios(config)
            .then((res) => {

                if (res.status === 200) {
                    setProcessing(false);

                    // Check if Content-Disposition header exists
                    const contentDisposition = res.headers["content-disposition"];
                    if (contentDisposition) {
                        // Extract filename from Content-Disposition header
                        const matches = contentDisposition.match(/filename="(.+?)"/);
                        if (matches) {
                            fileName = matches[1]; // Set filename dynamically
                        }
                    }

                    // Create a URL for the blob
                    const blob = new Blob([res.data], {type: contentType});
                    const link = document.createElement("a");
                    link.href = window.URL.createObjectURL(blob);
                    link.download = fileName;
                    document.body.appendChild(link);
                    link.click();
                    document.body.removeChild(link);

                    // alert("Excel downloaded successfully.");

                    successAndGoBackAlert(
                        "Downloaded",
                        "Overall Summary Report download successfully",
                        false
                    );
                }
            })
            .catch((err) => {
                console.log(err);
            });
    };

    useEffect(() => {
    }, []);

    return useMemo(() => {
        return (
            <>
                <TableContainer
                    component={Paper}
                    sx={{maxWidth: "100%", overflowX: "auto"}}
                >
                    <Table
                        aria-label="collapsible table"
                        sx={{minWidth: "250px !important"}}
                    >
                        <TableHead>
                            <TableRow sx={{backgroundColor: "#065036"}}>


                                {/* <TableCell /> */}


                                <TableCell>
                                    <Grid
                                        display="flex"
                                        direction="row"
                                        container
                                        alignItems="center"
                                    >
                                        <AppsOutlined sx={{color: "#FFF"}}/>
                                        <Typography
                                            paddingLeft={1}
                                            className="OverviewCardTableHeader"
                                        >
                                            Stages
                                        </Typography>
                                    </Grid>
                                </TableCell>
                                <TableCell align="center">
                                    <Grid
                                        display="flex"
                                        direction="row"
                                        container
                                        alignItems="center"
                                    >
                                        <SummarizeOutlined sx={{color: "#FFF"}}/>
                                        <Typography
                                            paddingLeft={1}
                                            className="OverviewCardTableHeader"
                                        >
                                            Total Request
                                        </Typography>
                                    </Grid>
                                </TableCell>


                                {/*{*/}

                                {/*    isARDBCusReqTabActive(cusReqTabIndex) === "Yes" && <TableCell align="center">*/}
                                {/*      <Grid*/}
                                {/*          display="flex"*/}
                                {/*          direction="row"*/}
                                {/*          container*/}
                                {/*          alignItems="center"*/}
                                {/*      >*/}
                                {/*        <ApprovalOutlined sx={{ color: "#FFF" }} />*/}
                                {/*        <Typography*/}
                                {/*            paddingLeft={1}*/}
                                {/*            className="OverviewCardTableHeader"*/}
                                {/*        >*/}
                                {/*          HO Approved (Prep Stage)*/}
                                {/*        </Typography>*/}
                                {/*      </Grid>*/}
                                {/*    </TableCell>*/}
                                {/*}*/}


                                <TableCell align="center">
                                    <Grid
                                        display="flex"
                                        direction="row"
                                        container
                                        alignItems="center"
                                    >
                                        <AppRegistrationOutlined sx={{color: "#FFF"}}/>
                                        <Typography
                                            paddingLeft={1}
                                            className="OverviewCardTableHeader"
                                        >
                                            Open Request
                                        </Typography>
                                    </Grid>
                                </TableCell>
                                <TableCell
                                    //   sx={{ display: { sm: "none", md: "table-cell" } }}
                                    align="center"
                                >
                                    <Grid
                                        display="flex"
                                        direction="row"
                                        container
                                        alignItems="center"
                                    >
                                        {/* <AddchartOutlined sx={{ color: "#FFF" }} /> */}
                                        <AssignmentTurnedInIcon sx={{color: "#FFF"}}/>
                                        <Typography
                                            paddingLeft={1}
                                            className="OverviewCardTableHeader"
                                        >
                                            Closed Request
                                        </Typography>
                                    </Grid>
                                </TableCell>


                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {data.CusBucket.map((row) => (
                                <OverviewCardStagesListPenAndClosedOnly key={row.name} row={row}/>
                            ))}
                        </TableBody>
                    </Table>
                </TableContainer>

                <Grid container display="flex" justifyContent={"right"}>

                    <Paper elevation={2} sx={{color: "#065036", mt: 1}}>
                        <Grid>
                            {
                                processing ?
                                    <Grid p={1}  display="flex"
                                          direction="row">
                                        Downloading ... <CircularProgress size="1rem"/>
                                    </Grid>
                                    :
                                    <Grid p={1}  display="flex"
                                           direction="row" onClick={() => downloadCusReq()}
                                          className="cursorPoint">
                                        <span>Summary Report</span>
                                        <CloudDownload sx={{color: "#065036", ml: 1}}/>
                                    </Grid>
                            }

                        </Grid>
                    </Paper>

                </Grid>


            </>
        );
    }, [data, processing]);
};
