import {Button, CircularProgress, Divider, Grid} from "@mui/material";
import {
    cusReqMasterDataAtom,
    SubmitErrorAlertAtom,
    useRecoilState,
    renderSubmitErrorAlert,
    ErrorLabelAtom,
    isObjectCus,
    isEmptyObject,
    successAndGoBackAlert,
    paramsFromURL,
    linkToSplit_customizationrequest,
    invalidURLAlert,
    isFeedbackDatesNotOkay,
    stakeholderInputErrorDesc,
    cleanGarbageCharacters,
    cusReqSubmitBtnAccessible
} from "../../../../Heplers";
import React, {useMemo, useState, useRef} from "react";
import SaveAsIcon from '@mui/icons-material/SaveAs';
import axiosInstance from "../../../../../Services/AxiosInstance";
import {useNavigate} from "react-router-dom";
import {getCookie} from "../../../../../Services/Cookies";

export const MasterDataSubmit = (props) => {
    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] = useRecoilState(SubmitErrorAlertAtom);

    const noOfInputErrors = useRef(0);

    const [loading, setLoading] = useState(false)

    const urlParams = paramsFromURL({linkToSplit: linkToSplit_customizationrequest})

    const navigate = useNavigate();

    const saveFormData = () => {
        !ErrorLabel && setErrorLabel(true);

        noOfInputErrors.current = 0;

        // const reqData: x = structuredClone(Atom);
        let reqData = {}

        // console.log('before clean', Atom)

        for (const [key, value] of Object.entries(Atom)) {

            console.log(`Checking ${key} -> ${value} | type of ${typeof value}`);

            if (typeof value === 'string' || typeof value === 'number' || (isObjectCus(value) && !isEmptyObject(value))) {
                // console.log(`${key}: ${value}`);
                reqData[key] = cleanGarbageCharacters(value)
            }
        }

        // console.log('mid clean', reqData)

        // Checking null empty key and removing it
        for (const [key, value] of Object.entries(reqData)) {

            // console.log(`Checking ${key} -> ${value}`);
            if (value == null || (typeof value === 'string' && value.length == 0) || (isObjectCus(value) && isEmptyObject(value))) {

                // console.log(`Deleting ${key} -> ${value}`);

                delete reqData[key];
            }
        }

        // console.log('after clean', reqData)
        const requiredKeyName = ["state", "bucket", "descrip", "dor", "edor", "addvia", "addto", "portal", "module", "type_of_change", "deviation", "showstopper", "assigned_to", "ardb_pacs",];


        console.log(reqData, Atom);
        // return;

        requiredKeyName.forEach((v, i) => {
            // console.log(v, reqData[v]);

            if (reqData[v] === undefined || reqData[v].length === 0 || Object.keys(reqData[v]).length === 0) {
                noOfInputErrors.current++;
            }

            if (i + 1 === requiredKeyName.length && noOfInputErrors.current > 0) {
                // console.log("setting Alert", noOfInputErrors.current);
                setSubmitErrorAlert(true);
                setTimeout(() => {
                    window.scrollTo({left: 0, top: document.body.scrollHeight, behavior: "smooth"});
                }, 500);
            }
        });

        // return;

        if (noOfInputErrors.current === 0) {

            // Setting DropDown Object options for required field directly
            reqData.state = Atom.state.code;
            reqData.bucket = Atom.bucket.id;
            reqData.addvia = Atom.addvia.id;
            reqData.portal = Atom.portal.id;
            reqData.module = Atom.module.id;
            reqData.type_of_change = Atom.type_of_change.id;
            reqData.deviation = Atom.deviation.id;


            reqData.showstopper = Atom.showstopper.id;
            if (reqData.showstopper !== "Yes") {
                reqData.showstopper_pacs_no = 0
                reqData.showstopper_audit = "No"
                reqData.showstopper_dayend = 'No'
            } else {
                if (Atom.showstopper_audit !== undefined && Atom.showstopper_audit !== null && Atom.showstopper_audit.id !== undefined) reqData.showstopper_audit = Atom.showstopper_audit.id;
                if (Atom.showstopper_dayend !== undefined && Atom.showstopper_dayend !== null && Atom.showstopper_dayend.id !== undefined) reqData.showstopper_dayend = Atom.showstopper_dayend.id;
            }


            // TODO: SHOWSTOPPER DAYEND AND AUIDT CHECK
            // if(reqData.showstopper_dayend !== 'Yes' && reqData.showstopper_audit !== 'Yes'){
            //     return invalidURLAlert(`Error Showstopper Dayend or Audit`, "Please select 'Yes' for atleast one parameter ", '', false);
            // }


            // Setting DropDown Object options for required field if data available
            if (Atom.pacs_status !== undefined && Atom.pacs_status.id !== undefined) reqData.pacs_status = Atom.pacs_status.id
            if (isFeedbackDatesNotOkay('pacs', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error PACS Feedback`, stakeholderInputErrorDesc, '', false);
            }


            if (Atom.si_status !== undefined && Atom.si_status.id !== undefined) reqData.si_status = Atom.si_status.id;
            if (isFeedbackDatesNotOkay('si', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error SI Feedback`, stakeholderInputErrorDesc, '', false);
            }


            if (Atom.stcb_status !== undefined && Atom.stcb_status.id !== undefined) reqData.stcb_status = Atom.stcb_status.id;
            if (isFeedbackDatesNotOkay('stcb', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error StCB Feedback`, stakeholderInputErrorDesc, '', false);
            }

            // return

            if (Atom.state_status !== undefined && Atom.state_status.id !== undefined) reqData.state_status = Atom.state_status.id;
            if (isFeedbackDatesNotOkay('state', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error State Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.spmu_status !== undefined && Atom.spmu_status.id !== undefined) reqData.spmu_status = Atom.spmu_status.id;
            if (isFeedbackDatesNotOkay('spmu', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error SPMU Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.ro_status !== undefined && Atom.ro_status.id !== undefined) reqData.ro_status = Atom.ro_status.id;
            if (isFeedbackDatesNotOkay('ro', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error RO Feedback`, stakeholderInputErrorDesc, '', false);
            }


            if (Atom.slimc_status !== undefined && Atom.slimc_status.id !== undefined) reqData.slimc_status = Atom.slimc_status.id;
            if (isFeedbackDatesNotOkay('slimc', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error SLIMC Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.cpmu_status !== undefined && Atom.cpmu_status.id !== undefined) reqData.cpmu_status = Atom.cpmu_status.id;
            if (isFeedbackDatesNotOkay('cpmu', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error CPMU Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.ho_status !== undefined && Atom.ho_status.id !== undefined) reqData.ho_status = Atom.ho_status.id;
            if (isFeedbackDatesNotOkay('ho', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error HO Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.nlpsv_status !== undefined && Atom.nlpsv_status.id !== undefined) reqData.nlpsv_status = Atom.nlpsv_status.id;
            if (isFeedbackDatesNotOkay('nlpsv', reqData, 'dor', (urlParams.paramId !== undefined && urlParams.paramId != ""))) {
                return invalidURLAlert(`Error NLPSV Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.priority !== undefined && Atom.priority.id !== undefined) reqData.priority = Atom.priority.id;

            if (Atom.assigned_to !== undefined && Atom.assigned_to.id !== undefined) reqData.assigned_to = Atom.assigned_to.id;

            if (Atom.ardb_pacs !== undefined && Atom.ardb_pacs.id !== undefined) reqData.ardb_pacs = Atom.ardb_pacs.id;

            if (Atom.integration_type !== undefined && Atom.integration_type !== null && Atom.integration_type.id !== undefined) reqData.integration_type = Atom.integration_type.id;


            // Setting ResourceID means loggedIn UserID
            reqData.user_id = getCookie('resourceId');

            let url = "savePreparation_CusReq"
            // @ts-ignore
            if (urlParams.paramId !== undefined && urlParams.paramId != "") {
                url = 'updatePreparation_CusReq'
            }

            setLoading(true)
            axiosInstance({method: "post", url, data: reqData}).then(function (response) {
                setLoading(false)
                // console.log(response.data);

                successAndGoBackAlert(`CUI: ${response.data.cui}`, `Customization Request - successfully ${(urlParams.paramId !== undefined && urlParams.paramId != "") ? 'saved' : 'updated'} in the system`)
            })
                .catch(function (error) {
                    setLoading(false)
                    console.error(error);
                });
        }


    };

    return useMemo(() => {

        // console.log({Atom});

        return (<>
                <Grid container direction="row" justifyContent="flex-end">
                    <Grid item xs={12} my={2}>
                        <Divider/>
                    </Grid>
                    <Button
                        onClick={() => navigate(-1)}
                        sx={{mt: 1, textTransform: 'none'}}
                        variant="outlined"
                        color="error"
                    >
                        Cancel
                    </Button>

                    {cusReqSubmitBtnAccessible(Atom) && <Button
                        onClick={() => saveFormData()}
                        sx={{mt: 1, ml: 1, textTransform: 'none'}}
                        variant="contained"
                        color="success"

                        disabled={loading}
                        // disabled={true}
                    >
                        {loading ? <>Saving ... <CircularProgress size={16}
                                                                  color="success"/></> : <>Submit{"  "}<SaveAsIcon
                            sx={{fontSize: 14, ml: 1}}/></>}
                    </Button>}
                </Grid>
                {renderSubmitErrorAlert(SubmitErrorAlert, noOfInputErrors.current)}
            </>);
    }, [ErrorLabel, SubmitErrorAlert, loading, Atom]);
};
