import axios from "axios";
import { API_Endpoint } from "../RAS_updates/Heplers";
import { jwtDecode } from "jwt-decode";
import { clearCookie, getCookie } from "./Cookies";

const key1 =
  "wVgGhlIOKAnFRleHQgdG8gQmFzZTY04oCdIGNvbnZlcnRlciBpcyBhIHNpbXBsZSBlbmNvZGVyIHRvb2wgdGhhdCBhbGxvd3MgeW91IHRvIGNvbnZlcnQgb25saW5lIHRleHQgdG8gQmFzZTY0ICh0aGF0IGlzLCBpdCBlbmNvZGVzIGFueSB0ZXh0dWFsIGNoYXJhY3RlcnMgaW50byBhIGJhc2ljIEFTQ0lJIHN0cmluZyku";
const key2 =
  "wRG8geW91IGhhdmUgdG8gZGVhbCB3aXRoIEJhc2U2NCBmb3JtYXQ/IFRoZW4gdGhpcyBzaXRlIGlzIHBlcmZlY3QgZm9yIHlvdSEgVXNlIG91ciBzdXBlciBoYW5keSBvbmxpbmUgdG9vbCB0byBlbmNvZGUgb3IgZGVjb2RlIHlvdXIgZGF0YXNldC4u";

  function isTokenExpired(token) {
  if (!token) return true;
  try {
    const decoded = jwtDecode(token);
    if (!decoded.exp) return true;
    const now = Date.now() / 1000;
    return decoded.exp < now;
  } catch (e) {
    return true;
  }
}

const axiosInstance = axios.create({
  baseURL:
    // Dynamic Check ...
    API_Endpoint(),

  headers: {
    "Content-Type": "application/json",
    email: getCookie("email2"),
    "access-token": getCookie("token"),
    Authorization: `Bearer ${getCookie("token")}`,
  },
});

export const logOutURL = () => {
  if (
    String(window.location.href).toLocaleLowerCase().indexOf("/dev_server") !== -1) {
    return "/dev_server"
  } else if (String(window.location.href).toLocaleLowerCase().indexOf("/aws_server") !== -1) {
    return "/aws_server"
  } else if (String(window.location.href).toLocaleLowerCase().indexOf("/prod_server") !== -1) {
    return "/prod_server"
  }
  return "/"
}

axiosInstance.interceptors.request.use(
  (config) => {
    // Skip token check for login API
    if (
      config.url &&
      config.url.includes("/login")
    ) {
      return config;
    }
    const token = getCookie("token");
    // Only check expiry if token exists
    if (token && isTokenExpired(token) &&
        (String(window.location.hostname).toLocaleLowerCase() !== "127.0.0.1"
            && String(window.location.hostname).toLocaleLowerCase() !== "localhost")
    ) {
      logOutURL();
      clearCookie("email2");
      clearCookie("token");
      clearCookie("userName");
      clearCookie("loginStatus");
      clearCookie("userRole");
      clearCookie("state");
      clearCookie("email");
      clearCookie("resourceId");
      window.location.href = logOutURL();
      return Promise.reject(new Error("Session expired. Redirecting to Dashboard."));
    }
    return config;
  },
  (error) => Promise.reject(error)
);

axiosInstance.interceptors.response.use(
  (response) => {
    // console.log("axiosInstance first response => ", response);
    if (response.status === 200 || response.status === 201) {
      //  // o.s.v.a.LifecycleAwareSessionManager     : Cannot enhance VaultToken to a LoginToken: Token self-lookup failed

      // TODO:CHECK Before Commit
      //With Encryption
      const dataWithoutKeys = response.data.replace(key1, "").replace(key2, "");
      const decodedData = JSON.parse(atob(dataWithoutKeys));
      response.data = decodedData;
      
      console.log("axiosInstance returning response => ", response);
      return response;
      // Without Encryption on Local
      if (
        window.location.hostname !== "localhost" &&
        window.location.hostname !== "127.0.0.1"
      ) {
        const dataWithoutKeys = response.data
          .replace(key1, "")
          .replace(key2, "");
        const decodedData = JSON.parse(atob(dataWithoutKeys));
        response.data = decodedData;
      }
    }

    // console.log("axiosInstance returning response => ", response);
    return response;
  },
  (error) => {
    return Promise.reject(error);
  }
);

export default axiosInstance;
