import React, { useEffect, useMemo } from 'react';
import { useRecoilValue, pageLoadingAtom, dataListingLoadingAtom } from '../../../Heplers/';
import { Card, Grid, LinearProgress, Typography } from '@mui/material';

export const PageLoadingElem = ({text = "Please wait page loading ..."}) => {
    const loading = useRecoilValue(pageLoadingAtom);
    return useMemo(() => {
        return loading ? <><Grid item container pt={5}>
            <Typography fontSize={12} color={'GrayText'}>{text}</Typography>

        </Grid>
            <LinearProgress color="success" /></> : null
    }, [loading])
};

export const DataListingLoadingElem = ({text ="Please wait loading ...", mt = 3}) => {
    const loading = useRecoilValue(dataListingLoadingAtom);
    return useMemo(() => {
        return loading ? <Card sx={{ width: "100%", mt }}><Grid item container py={3} justifyContent={"center"}>
            <Typography fontSize={12} color={'GrayText'}>{text}</Typography>

        </Grid>
            <LinearProgress color="success" /></Card> : null
    }, [loading])
};