import {
  Divider,
  Grid,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  TextField,
} from "@mui/material";
import {
  SubmitErrorAlertAtom,
  useRecoilState,
  renderInputErrorLabel,
  ErrorLabelAtom,
  isEmptyObject,
  formatDate,
  isObjectCus,
  genUUID,
  cusReqDEVMasterDataAtom,
  currentDatePlus14,
  currentDate,
  cusReqCUIMasterDetailsAtom,
  useRecoilValue,
} from "../../../../Heplers";
import React, { useEffect, useMemo } from "react";
import { defTextFieldOnChange, InputsFourthRowMasterData } from "..";

export const InputsFirstRowDEV = ({readOnly}) => {
  const [Atom, setAtom] = useRecoilState(cusReqDEVMasterDataAtom);
  // forCheckingInputErrorLabelOnlyAfterSubmit
  // @ts-ignore
  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const defTextFieldOnChangeComParams = {
    setAtom,
    SubmitErrorAlert,
    setSubmitErrorAlert,
  };

  const renderSavedbrd_points = () => {
    // @ts-ignore
    if (Atom !== null && typeof Atom.brd_points === "string") {
      // @ts-ignore
      const brd_points =
        Atom.brd_points !== null ? JSON.parse(`[${Atom.brd_points}]`) : [];
      return (
        <List sx={{ width: "100%", bgcolor: "background.paper" }}>
          {brd_points.map((value, i) => {
            const labelId = `checkbox-list-label-${value.name}`;

            return (
              <span key={genUUID()}>
                <ListItem
                  key={value}
                  //   secondaryAction={
                  //     <IconButton edge="end" aria-label="comments">
                  //       <CommentIcon />
                  //     </IconButton>
                  //   }
                  disablePadding
                >
                  <ListItemButton
                    role={undefined}
                    // onClick={handleToggle(value)}

                    dense
                  >
                    <ListItemIcon>
                      {/* <Checkbox
                                            edge="start"
                                            checked={checked.indexOf(value) !== -1}
                                            tabIndex={-1}
                                            disableRipple
                                            inputProps={{ 'aria-labelledby': labelId }}
                                        /> */}
                      <b>{i + 1}:</b>
                    </ListItemIcon>
                    <ListItemText id={labelId} primary={value.name} />
                  </ListItemButton>
                </ListItem>
                <Divider variant="inset" component="li" />
              </span>
            );
          })}
        </List>
      );
    }

    return null;
  };

  const CUIAtom = useRecoilValue(cusReqCUIMasterDetailsAtom);
  useEffect(() => {
    // Setting Default Value
    // console.log(Atom)
    // For Update Form
    if (
      CUIAtom !== null &&
      CUIAtom.dev !== null &&
      isObjectCus(CUIAtom.dev) &&
      !isEmptyObject(CUIAtom.dev)
    ) {
      defTextFieldOnChange(
        formatDate(Atom.edor, "db-yyyy-mm-dd"),
        "edor",
        defTextFieldOnChangeComParams
      );
      defTextFieldOnChange(
        formatDate(Atom.dod, "db-yyyy-mm-dd"),
        "dod",
        defTextFieldOnChangeComParams
      );
      defTextFieldOnChange(
        formatDate(Atom.dsd, "db-yyyy-mm-dd"),
        "dsd",
        defTextFieldOnChangeComParams
      );
      defTextFieldOnChange(
        Atom.nlpsv_resource_name,
        "nlpsv_resource_name",
        defTextFieldOnChangeComParams
      );
      // defTextFieldOnChange(Atom.addto, "addto", defTextFieldOnChangeComParams);
    } else {
      defTextFieldOnChange(currentDate, "dsd", defTextFieldOnChangeComParams);
      defTextFieldOnChange(
        currentDatePlus14,
        "dod",
        defTextFieldOnChangeComParams
      );
      defTextFieldOnChange(
        currentDatePlus14,
        "edor",
        defTextFieldOnChangeComParams
      );
    }
  }, []);

  return useMemo(() => {
    return (
      <Grid spacing={2} container>
        <Grid item xs={12} md={6} sx={{ pb: { xs: 2 }, pt: { md: 1 } }}>
          <TextField
            label="Started On"
            variant="outlined"
            type="date"
            defaultValue={
              Atom !== null && typeof Atom.dsd === "string"
                ? formatDate(Atom.dsd, "db-yyyy-mm-dd")
                : currentDate
            }
            fullWidth
            required
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(e) =>
             readOnly ? null : defTextFieldOnChange(
                e.target.value,
                "dsd",
                defTextFieldOnChangeComParams
              )
            }

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {renderInputErrorLabel(ErrorLabel, Atom.dsd, "Required")}
        </Grid>

        <Grid item xs={12} md={6} sx={{ pb: { xs: 2 }, pt: { md: 1 } }}>
          <TextField
            label="Expected Date of Development Resolution"
            variant="outlined"
            type="date"
            defaultValue={
              Atom !== null && typeof Atom.edor === "string"
                ? formatDate(Atom.edor, "db-yyyy-mm-dd")
                : currentDatePlus14
            }
            fullWidth
            required
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(e) =>
              readOnly ?  null : defTextFieldOnChange(
                e.target.value,
                "edor",
                defTextFieldOnChangeComParams
              )
            }

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {renderInputErrorLabel(ErrorLabel, Atom.edor, "Required")}
        </Grid>

        <Grid item xs={12} md={6} sx={{ pb: { xs: 2 }, pt: { md: 1 } }}>
          <TextField
            label="NLPSV Resource Name"
            variant="outlined"
            defaultValue={
              Atom !== null && typeof Atom.nlpsv_resource_name === "string"
                ? Atom.nlpsv_resource_name
                : null
            }
            fullWidth
            required
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(e) =>
             readOnly ? null : defTextFieldOnChange(
                e.target.value,
                "nlpsv_resource_name",
                defTextFieldOnChangeComParams
              )
            }

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {renderInputErrorLabel(
            ErrorLabel,
            Atom.nlpsv_resource_name,
            "Required"
          )}
        </Grid>

        <Grid item xs={12} md={6} sx={{ pb: { xs: 2 }, pt: { md: 1 } }}>
          <TextField
            label="Development Reviewed On"
            variant="outlined"
            type="date"
            defaultValue={
              Atom !== null && typeof Atom.dod === "string"
                ? formatDate(Atom.dod, "db-yyyy-mm-dd")
                : currentDatePlus14
            }
            fullWidth
            required
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(e) =>
             readOnly ? null : defTextFieldOnChange(
                e.target.value,
                "dod",
                defTextFieldOnChangeComParams
              )
            }

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {renderInputErrorLabel(ErrorLabel, Atom.dod, "Required")}
        </Grid>

        <Grid item xs={12} md={6} sx={{ pb: { xs: 2 }, pt: { md: 1 } }}>
          <InputsFourthRowMasterData
            formAtom={cusReqDEVMasterDataAtom}
            md={12}
            mt={0}

            readOnly={readOnly}
          />
        </Grid>
        {/* 
                {renderSavedbrd_points()}


                <Grid item xs={12} md={12}>
                    <Autocomplete
                        // @ts-ignore
                        onChange={(e, v) => defTextFieldOnChange(v, "brd_points", defTextFieldOnChangeComParams)}
                        multiple
                        id="tags-filled"
                        options={[].map((option) => option.title)}
                        // defaultValue={[top100Films[13].title]}
                        freeSolo
                        sx={{ width: "100%" }}
                        renderTags={(value, getTagProps) =>
                            value.map((option, index) => {
                                const { key, ...tagProps } = getTagProps({ index });
                                return (
                                    <Chip
                                        variant="outlined"
                                        label={option}
                                        key={key}
                                        {...tagProps}
                                    />
                                );
                            })
                        }
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                id="outlined-multiline-static"
                                label="BRD summary points"
                                multiline
                                variant="outlined"
                                // rows={2}
                                InputLabelProps={{ shrink: true }}
                                fullWidth
                                // @ts-ignore
                                required={(Atom.brd_points !== undefined && Atom.brd_points === null)}
                            // sx={{
                            //   // minWidth: '450px
                            //   paddingRight: '4%'
                            // }}
                            />
                        )}
                    />
                    {renderInputErrorLabel(ErrorLabel, Atom.brd_points !== undefined && Atom.brd_points, "Required")}
                </Grid> */}
      </Grid>
    );
  }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
