import {Alert, Button, CircularProgress, Divider, Grid} from "@mui/material";
import {
    SubmitErrorAlertAtom,
    useRecoilState,
    renderSubmitErrorAlert,
    ErrorLabelAtom,
    useRecoilValue,
    isObjectCus,
    isEmptyObject,
    cusReqUATMasterDataAtom,
    successAndGoBackAlert,
    cusReqCUIMasterDetailsAtom,
    paramsFromURL,
    invalidURLAlert,
    isFeedbackDatesNotOkay,
    stakeholderInputErrorDesc, cusReqSubmitBtnAccessible
} from "../../../../Heplers";
import React, {useMemo, useState, useRef} from "react";
import SaveAsIcon from '@mui/icons-material/SaveAs';
import axiosInstance from "../../../../../Services/AxiosInstance";
import {useNavigate} from "react-router-dom";
import {getCookie} from "../../../../../Services/Cookies";

export const UATDataSubmit = (props) => {
    const [Atom, setAtom] = useRecoilState(cusReqUATMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);

    const cardDetailsAtom = useRecoilValue(cusReqCUIMasterDetailsAtom);

    const noOfInputErrors = useRef(0);

    const [loading, setLoading] = useState(false)
    const URLParams = paramsFromURL({
        linkToSplit: "customizationrequestuat/",
    })
    const navigate = useNavigate();
    const saveFormData = () => {
        !ErrorLabel && setErrorLabel(true);

        noOfInputErrors.current = 0;

        // const reqData: x = structuredClone(Atom);
        // @ts-ignore
        let reqData = {cui: URLParams.paramId}

        // Object.keys(obj).forEach(function(key, idx, arr){

        // })
        for (const [key, value] of Object.entries(Atom)) {
            if (typeof value === 'string' || typeof value === 'number' || (isObjectCus(value) && !isEmptyObject(value))) {
                // console.log(`${key}: ${value}`);
                if (Array.isArray(value)) {
                    reqData[key] = value.join(':#:')
                } else {
                    reqData[key] = value
                }

            }
        }

        // Checking null empty key and removing it
        for (const [key, value] of Object.entries(reqData)) {

            console.log(`Checking ${key} -> ${value}`);
            if (value == null || (typeof value === 'string' && value.length == 0) || (isObjectCus(value) && isEmptyObject(value))) {

                // console.log(`Deleting ${key} -> ${value}`);

                delete reqData[key];
            }
        }

        const requiredKeyName = [
            "start_date",
            "dod", "assigned_to"
        ];


        // console.log(reqData, Atom);
        // return;
        requiredKeyName.forEach((v, i) => {
            // console.log(v, reqData[v]);

            if (
                reqData[v] === undefined ||
                reqData[v].length === 0 ||
                Object.keys(reqData[v]).length === 0
            ) {
                noOfInputErrors.current++;
            }

            if (i + 1 === requiredKeyName.length && noOfInputErrors.current > 0) {
                // console.log("setting Alert", noOfInputErrors.current);
                setSubmitErrorAlert(true);
                // setTimeout(() => {
                //     window.scrollTo({ left: 0, top: document.body.scrollHeight, behavior: "smooth" });
                // }, 500);
            }
        });

        if (noOfInputErrors.current === 0) {

            // Setting DropDown Object options for required field directly
            // reqData.state = Atom.state.code;
            // reqData.bucket = Atom.bucket.id;

            // Setting DropDown Object options for required field if data available
            if (Atom.acceptance_si !== undefined && Atom.acceptance_si.id !== undefined)
                reqData.acceptance_si = Atom.acceptance_si.id;

            if (Atom.acceptance_state !== undefined && Atom.acceptance_state.id !== undefined)
                reqData.acceptance_state = Atom.acceptance_state.id;

            if (Atom.acceptance_ro !== undefined && Atom.acceptance_ro.id !== undefined)
                reqData.acceptance_ro = Atom.acceptance_ro.id;

            if (Atom.si_status !== undefined && Atom.si_status.id !== undefined)
                reqData.si_status = Atom.si_status.id;

            if (isFeedbackDatesNotOkay('si', reqData, 'start_date', cardDetailsAtom.uat !== null)) {
                return invalidURLAlert(`Error SI Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.state_status !== undefined && Atom.state_status.id !== undefined)
                reqData.state_status = Atom.state_status.id;
            if (isFeedbackDatesNotOkay('state', reqData, 'start_date', cardDetailsAtom.uat !== null)) {
                return invalidURLAlert(`Error State Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.stcb_status !== undefined && Atom.stcb_status.id !== undefined)
                reqData.stcb_status = Atom.stcb_status.id;
            if (isFeedbackDatesNotOkay('stcb', reqData, 'start_date', (cardDetailsAtom.paramId !== undefined && cardDetailsAtom.paramId != ""))) {
                return invalidURLAlert(`Error StCB Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.ro_status !== undefined && Atom.ro_status.id !== undefined)
                reqData.ro_status = Atom.ro_status.id;

            if (isFeedbackDatesNotOkay('ro', reqData, 'start_date', cardDetailsAtom.uat !== null)) {
                return invalidURLAlert(`Error RO Feedback`, stakeholderInputErrorDesc, '', false);
            }

            if (Atom.nlpsv_status !== undefined && Atom.nlpsv_status.id !== undefined)
                reqData.nlpsv_status = Atom.nlpsv_status.id;

            if (isFeedbackDatesNotOkay('nlpsv', reqData, 'start_date', cardDetailsAtom.uat !== null)) {
                return invalidURLAlert(`Error NLPSV Feedback`, stakeholderInputErrorDesc, '', false);
            }


            if (Atom.assigned_to !== undefined && Atom.assigned_to.id !== undefined)
                reqData.assigned_to = Atom.assigned_to.id;

            // Setting ResourceID means loggedIn UserID
            reqData.user_id = getCookie('resourceId');

            setLoading(true)
            axiosInstance({
                method: "post",
                url: cardDetailsAtom.uat === null ? "saveUAT_CusReq" : "updateUAT_CusReq",
                data: reqData
            }).then(function (response) {
                setLoading(false)
                // console.log(response.data);

                successAndGoBackAlert(`CUI: ${response.data.cui}`, `Customization Request - successfully updated in the system`)
            })
                .catch(function (error) {
                    setLoading(false)
                    console.error(error);
                });
        }


    };

    return useMemo(() => {

        // console.log({ cardDetailsAtom })

        const isReOpenedPreviousStageClosed = (cardDetailsAtom.dev !== undefined && cardDetailsAtom.dev.dev_reviews_ongoing !== undefined && JSON.parse(cardDetailsAtom.dev.dev_reviews_ongoing).inputs_closed !== undefined && JSON.parse(cardDetailsAtom.dev.dev_reviews_ongoing).inputs_closed === 'Yes');

        return (
            <>
                <Grid container direction="row" justifyContent="flex-end">
                    <Grid item xs={12} my={2}>
                        <Divider/>
                    </Grid>

                    {
                        !isReOpenedPreviousStageClosed && <>
                            <Alert variant="filled" severity="warning">
                                This is a pushed back/reopened request. You must close all previous stages to make changes in the current stage.
                            </Alert>
                            <Grid item xs={12} my={2}>
                                <Divider/>
                            </Grid>
                        </>
                    }

                    <Button
                        onClick={() => navigate(-1)}
                        sx={{mt: 1, textTransform: 'none'}}
                        variant="outlined"
                        color="error"
                    >
                        Cancel
                    </Button>

                    {
                        (cusReqSubmitBtnAccessible(Atom) && isReOpenedPreviousStageClosed) && <Button
                            onClick={() => saveFormData()}
                            sx={{mt: 1, ml: 1, textTransform: 'none'}}
                            variant="contained"
                            color="success"

                            disabled={loading}
                            // disabled={true}
                        >
                            {loading ? <>Saving ... <CircularProgress size={16}
                                                                      color="success"/></> : <>Submit{"  "}<SaveAsIcon
                                sx={{fontSize: 14, ml: 1}}/></>}
                        </Button>
                    }
                </Grid>
                {renderSubmitErrorAlert(SubmitErrorAlert, noOfInputErrors.current)}
            </>
        );
    }, [ErrorLabel, SubmitErrorAlert, loading, Atom]);
};
