import { Divider, Grid, TextField, Typography } from "@mui/material";
import {
  SubmitErrorAlertAtom,
  useRecoilState,
  ErrorLabelAtom,
  isEmptyObject,
  formatDate,
  StakeholderStatusArr,
  cusReqNLPSVStatusListAtom,
  isObjectCus,
  currentDatePlus14
} from "../../../../Heplers";
import React, { useEffect, useMemo } from "react";
import { CusReqDropdown, defTextFieldOnChange } from "..";
import {getCookie} from "../../../../../Services/Cookies";

export const NLPSVInputs = ({ formAtom, md, edodInput, edorfInput, readOnly, plannedGoLive }) => {

  const [Atom, setAtom] = useRecoilState(formAtom);
  // forCheckingInputErrorLabelOnlyAfterSubmit
  const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
  const [SubmitErrorAlert, setSubmitErrorAlert] =
    useRecoilState(SubmitErrorAlertAtom);

  const defTextFieldOnChangeComParams = {
    setAtom, SubmitErrorAlert, setSubmitErrorAlert
  }

  useEffect(() => {
    // Setting Default Value
    // console.log(Atom)
    // For Update Form
    if (!isEmptyObject(Atom)) {
      typeof Atom.nlpsv_inputs === 'string' && defTextFieldOnChange(Atom.nlpsv_inputs, "nlpsv_inputs", defTextFieldOnChangeComParams);

      typeof Atom.nlpsv_date === 'number' && defTextFieldOnChange(formatDate(Atom.nlpsv_date, 'db-yyyy-mm-dd'), "nlpsv_date", defTextFieldOnChangeComParams);

      typeof Atom.edorf === 'number' && defTextFieldOnChange(formatDate(Atom.edorf, 'db-yyyy-mm-dd'), "edorf", defTextFieldOnChangeComParams);
    } else {
      // console.log(" New Form Default Set like dates");

      edorfInput && defTextFieldOnChange(currentDatePlus14, "edorf", defTextFieldOnChangeComParams);

      plannedGoLive && defTextFieldOnChange(
          formatDate(Atom.go_live_date, "db-yyyy-mm-dd"),
          "go_live_date",
          defTextFieldOnChangeComParams
      );
    }
  }, []);

  if(getCookie("userRole") === "NLPSV"){
    readOnly = false;
  }

  return useMemo(() => {
    return (

      <Grid item spacing={2} xs={12} md={md} container direction={'column'}>

        <Grid item>
          <Divider textAlign="left" sx={{ width: "50%", my: 2 }}>
            <Typography color={'GrayText'} fontSize={13} fontWeight="700">NLPSV</Typography>
          </Divider>
          <TextField
            label="Date"
            variant="outlined"
            type="date"
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? formatDate(Atom.nlpsv_date, 'db-yyyy-mm-dd') : null}
            fullWidth
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "nlpsv_date", defTextFieldOnChangeComParams)}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
        </Grid>

        <Grid item>
          <CusReqDropdown
            // @ts-ignore
            formDataAtom={formAtom}
            listDataAtom={cusReqNLPSVStatusListAtom}
            ddLabel="Status"
            dropdownName={"nlpsv_status"}
            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? (Atom.nlpsv_status === null ? Atom.nlpsv_status : Atom.nlpsv_status) : null}
            optData={StakeholderStatusArr}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}
          />
          {/* @ts-ignore */}
        </Grid>

        <Grid item>
          <TextField
            label="Remarks"
            multiline
            variant="outlined"
            rows={4}
            fullWidth
            InputLabelProps={{
              shrink: true,
            }}
            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.nlpsv_inputs : null}
            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "nlpsv_inputs", defTextFieldOnChangeComParams)}

            disabled={readOnly}
            aria-readonly={readOnly}
            readOnly={readOnly}
            className={`${readOnly && 'readonlyStyle'}`}

          />
        </Grid>

        {edodInput && (
          <Grid item>
            <TextField
              label="Expected Date of Deployment"
              variant="outlined"
              type="date"
              defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? formatDate(Atom.edod, 'db-yyyy-mm-dd') : null}
              fullWidth
              InputLabelProps={{
                shrink: true,
              }}
              onChange={(e) => defTextFieldOnChange(e.target.value, "edod", defTextFieldOnChangeComParams)}

              disabled={readOnly}
              aria-readonly={readOnly}
              readOnly={readOnly}
              className={`${readOnly && 'readonlyStyle'}`}
            />
          </Grid>

        )}


        {edorfInput && (
          <Grid item>
            <TextField
              label="EDoR - Expected Date of Resolution"
              variant="outlined"
              type="date"
              defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? formatDate(Atom.edorf, 'db-yyyy-mm-dd') : currentDatePlus14}
              fullWidth
              InputLabelProps={{
                shrink: true,
              }}
              onChange={(e) => defTextFieldOnChange(e.target.value, "edorf", defTextFieldOnChangeComParams)}


              disabled={readOnly}
              aria-readonly={readOnly}
              readOnly={readOnly}
              className={`${readOnly && 'readonlyStyle'}`}
            />
          </Grid>

        )}

        {plannedGoLive && (
            <Grid item>
              <TextField
                  label="Planned Go-Live Date"
                  variant="outlined"
                  type="date"
                  defaultValue={
                    Atom !== null && typeof Atom.go_live_date === "string"
                        ? formatDate(Atom.go_live_date, "db-yyyy-mm-dd")
                        : null
                  }
                  fullWidth
                  InputLabelProps={{
                    shrink: true,
                  }}
                  onChange={(e) =>
                      readOnly ? null : defTextFieldOnChange(
                          e.target.value,
                          "go_live_date",
                          defTextFieldOnChangeComParams
                      )
                  }

                  disabled={readOnly}
                  aria-readonly={readOnly}
                  readOnly={readOnly}
                  className={`${readOnly && 'readonlyStyle'}`}
              />
            </Grid>
        )}
      </Grid>


    );
  }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
