import React, { useEffect } from "react";
import Box from "@mui/material/Box";
import { CssBaseline, Toolbar, Grid } from "@mui/material";
import DrawerComp from "../../Components/Drawer/drawer";
import MainHeader from "../../Components/Header/MainHeader";
import { SiHeaderComponnent } from "./siHeaderComponent";
import { useSetRecoilState } from "recoil";
import { siTableDataAtom } from "../../RAS_updates/Heplers";
import SearchComponent from "./searchComponent";

export default function SiPaymentsParent() {
  useEffect(() => {
    window.scrollTo({
      top: 0,
      left: 0,
      behavior: "smooth",
    });
  }, []);
  return (
    <div style={{ overflowX: "hidden" }}>
      <style>
        {`
            .css-10hburv-MuiTypography-root{
              font-size:11px !important;
              font-family: Poppins 
            }
            .css-yb0lig{
              font-size:12px !important
            }
            `}
      </style>
      <Box sx={{ display: "flex" }}>
        <CssBaseline />
        <MainHeader />
        <DrawerComp listName={"SI Payments"} />
        <Box
          component="main"
          sx={{
            flexGrow: 1,
            backgroundColor: "#f4faf8",
            p: 1
          }}>
          <Toolbar />


          <Grid
            item
            container
            spacing={2}
            xs={12}
            sx={{
              mt: "1.5%",
              pl: "-0.5%",
            }}
          >
              <SiHeaderComponnent />
              <SearchComponent/>
          </Grid>
        </Box>
      </Box>
    </div>
  );
}
