import {Grid, TextField} from "@mui/material";
import {
    cusReqBucketListAtom,
    cusReqMasterDataAtom,
    cusReqStateListAtom,
    SubmitErrorAlertAtom,
    useRecoilState,
    renderInputErrorLabel,
    ErrorLabelAtom,
    isEmptyObject,
    formatDate,
    cusReqAddViaListAtom,
    isObjectCus,
    currentDatePlus14,
    currentDate,
    paramsFromURL
} from "../../../../Heplers";
import React, {useEffect, useMemo} from "react";
import {CusReqDropdown} from "..";
import {getCookie} from "../../../../../Services/Cookies";


export const defTextFieldOnChange = (value, keyName, {setAtom, SubmitErrorAlert, setSubmitErrorAlert}) => {
    // console.log(e);

    SubmitErrorAlert && setSubmitErrorAlert(false);

    setAtom((prevState) => ({
        // @ts-ignore
        ...prevState,
        [keyName]: value === null ? {} : value,
    }));
};

export const InputsFirstRowMasterData = ({readOnly}) => {

    const [Atom, setAtom] = useRecoilState(cusReqMasterDataAtom);
    // forCheckingInputErrorLabelOnlyAfterSubmit
    const [ErrorLabel, setErrorLabel] = useRecoilState(ErrorLabelAtom);
    const [SubmitErrorAlert, setSubmitErrorAlert] =
        useRecoilState(SubmitErrorAlertAtom);

    const defTextFieldOnChangeComParams = {
        setAtom, SubmitErrorAlert, setSubmitErrorAlert
    }

    useEffect(() => {
        // Setting Default Value
        // console.log(Atom)
        // For Update Form
        if (!isEmptyObject(Atom)) {
            // console.log("Sett params", Atom.edor, formatDate(Atom.edor, 'db-yyyy-mm-dd'))
            defTextFieldOnChange(formatDate(Atom.dor, 'db-yyyy-mm-dd'), "dor", defTextFieldOnChangeComParams);
            defTextFieldOnChange(formatDate(Atom.edor, 'db-yyyy-mm-dd'), 'edor', defTextFieldOnChangeComParams);
            defTextFieldOnChange(Atom.descrip, "descrip", defTextFieldOnChangeComParams);
            defTextFieldOnChange(Atom.addto, "addto", defTextFieldOnChangeComParams);
        } else {
            // console.log(" New Form Default Set like dates");

            defTextFieldOnChange(currentDate, "dor", defTextFieldOnChangeComParams);
            defTextFieldOnChange(currentDatePlus14, "edor", defTextFieldOnChangeComParams);
        }
    }, []);


    const vertiInputsPadding = {
        pb: {xs: 2},
    };

    const URLParams = paramsFromURL({
        linkToSplit: "customizationrequest/",
    })

    return useMemo(() => {

        // console.log((isObjectCus(Atom) && !isEmptyObject(Atom) && formatDate(Atom.dor, 'db-yyyy-mm-dd') !== undefined) ? formatDate(Atom.dor, 'db-yyyy-mm-dd') : currentDate)
        return (
            <Grid container spacing={2} columns={12}>
                <Grid item md={4} xs={12}>
                    <Grid item sx={{...vertiInputsPadding, pt: {md: 1}}}>
                        <TextField
                            label="DoR - Date of Request"
                            variant="outlined"
                            type="date"
                            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom) && formatDate(Atom.dor, 'db-yyyy-mm-dd') !== undefined) ? formatDate(Atom.dor, 'db-yyyy-mm-dd') : currentDate}
                            fullWidth
                            required
                            InputLabelProps={{
                                shrink: true,
                            }}
                            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "dor", defTextFieldOnChangeComParams)
                            }

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}


                        />
                        {renderInputErrorLabel(ErrorLabel, Atom.dor, "Required")}
                    </Grid>

                    <Grid item sx={{...vertiInputsPadding}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqMasterDataAtom}
                            listDataAtom={cusReqStateListAtom}
                            ddLabel="State/ UT"
                            dropdownName={"state"}
                            required
                            fetchMasterDataURL="fetchStateMasterData_CusReq"
                            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.state : null}
                            // @ts-ignore
                            optionLabel={["StateNameAndCode", "name", "short_name", "code"]}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}

                        />
                        {/* @ts-ignore */}
                        {renderInputErrorLabel(ErrorLabel, Atom.state, "Required")}
                    </Grid>
                    <Grid item sx={{...vertiInputsPadding}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqMasterDataAtom}
                            listDataAtom={cusReqBucketListAtom}
                            ddLabel="Customization Category"
                            dropdownName={"bucket"}
                            required
                            fetchMasterDataURL="fetchBucketMasterData_CusReq"
                            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.bucket : null}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}
                        />
                        {renderInputErrorLabel(ErrorLabel, Atom.bucket, "Required")}
                    </Grid>
                </Grid>


                <Grid item md={4} xs={12} sx={{mt: {md: 1}}}>
                    <style>
                        {`
                              .css-8ewcdo-MuiInputBase-root-MuiOutlinedInput-root{
                                padding: 19.5px 14px !important
                              }
                            `}
                    </style>
                    <TextField
                        label="Customization Description"
                        multiline
                        variant="outlined"
                        rows={7}
                        fullWidth
                        required
                        InputLabelProps={{
                            shrink: true,
                        }}
                        defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.descrip : null}
                        onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "descrip", defTextFieldOnChangeComParams)}

                        disabled={readOnly}
                        aria-readonly={readOnly}
                        readOnly={readOnly}
                        className={`${readOnly && 'readonlyStyle'}`}
                    />
                    {renderInputErrorLabel(ErrorLabel, Atom.descrip, "Required")}
                </Grid>

                <Grid item md={4} xs={12}>
                    <Grid item sx={{...vertiInputsPadding, pt: {md: 1}}}>
                        <TextField
                            label="Expected Date of Preparation Resolution"
                            variant="outlined"
                            type="date"
                            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom) && formatDate(Atom.edor, 'db-yyyy-mm-dd') !== undefined) ? formatDate(Atom.edor, 'db-yyyy-mm-dd') : currentDatePlus14}
                            fullWidth
                            required
                            InputLabelProps={{
                                shrink: true,
                            }}
                            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "edor", defTextFieldOnChangeComParams)}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}
                        />
                        {renderInputErrorLabel(ErrorLabel, Atom.edor, "Required")}
                    </Grid>

                    <Grid item sx={{...vertiInputsPadding}}>
                        <CusReqDropdown
                            // @ts-ignore
                            formDataAtom={cusReqMasterDataAtom}
                            listDataAtom={cusReqAddViaListAtom}
                            ddLabel="Request addressed via"
                            dropdownName={"addvia"}
                            fetchMasterDataURL="fetchAddViaMasterData_CusReq"
                            required
                            defVal={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.addvia : null}

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}
                        />
                        {renderInputErrorLabel(ErrorLabel, Atom.addvia, "Required")}
                    </Grid>

                    <Grid item sx={{...vertiInputsPadding}}>
                        <TextField
                            label="Request addressed to | NLPSV Resource Name"
                            variant="outlined"
                            fullWidth
                            InputLabelProps={{shrink: true}}
                            defaultValue={(isObjectCus(Atom) && !isEmptyObject(Atom)) ? Atom.addto : null}
                            onChange={(e) => readOnly ? null : defTextFieldOnChange(e.target.value, "addto", defTextFieldOnChangeComParams)}
                            required

                            disabled={readOnly}
                            aria-readonly={readOnly}
                            readOnly={readOnly}
                            className={`${readOnly && 'readonlyStyle'}`}
                        />
                        {renderInputErrorLabel(ErrorLabel, Atom.addto, "Required")}
                    </Grid>
                </Grid>
            </Grid>
        );
    }, [Atom, ErrorLabel, SubmitErrorAlert]);
};
